{"command":"create","path":"/workspace/codebase/rust/src/node_path.rs","file_text":"//! Ports of the `path` primitives used by the JavaScript implementation so that
//! path handling stays byte-for-byte compatible with Node's POSIX semantics.

use std::env;

pub fn extname(path: &str) -> String {
    let base = basename(path);
    let bytes = base.as_bytes();
    let mut idx = None;
    for (i, b) in bytes.iter().enumerate() {
        if *b == b'.' && i != 0 {
            idx = Some(i);
        }
    }
    match idx {
        Some(i) => base[i..].to_string(),
        None => String::new(),
    }
}

pub fn basename(path: &str) -> String {
    let trimmed = path.trim_end_matches('/');
    if trimmed.is_empty() {
        return if path.starts_with('/') {
            String::new()
        } else {
            path.to_string()
        };
    }
    match trimmed.rfind('/') {
        Some(i) => trimmed[i + 1..].to_string(),
        None => trimmed.to_string(),
    }
}

pub fn dirname(path: &str) -> String {
    if path.is_empty() {
        return ".".to_string();
    }
    let trimmed = path.trim_end_matches('/');
    let source = if trimmed.is_empty() { path } else { trimmed };
    match source.rfind('/') {
        Some(0) => "/".to_string(),
        Some(i) => source[..i].to_string(),
        None => ".".to_string(),
    }
}

/// `path.join` for the two-segment case used during directory traversal.
pub fn join(dir: &str, name: &str) -> String {
    let joined = if dir.is_empty() {
        name.to_string()
    } else if name.is_empty() {
        dir.to_string()
    } else if dir.ends_with('/') {
        format!("{dir}{name}")
    } else {
        format!("{dir}/{name}")
    };
    normalize(&joined)
}

/// `path.resolve` against the current working directory.
pub fn resolve(path: &str) -> String {
    if path.starts_with('/') {
        return normalize(path);
    }
    let cwd = env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| "/".to_string());
    if path.is_empty() {
        return normalize(&cwd);
    }
    normalize(&format!("{cwd}/{path}"))
}

/// `path.normalize`: collapses duplicate separators and resolves `.`/`..`.
pub fn normalize(path: &str) -> String {
    if path.is_empty() {
        return ".".to_string();
    }
    let absolute = path.starts_with('/');
    let trailing_slash = path.ends_with('/');
    let mut parts: Vec<&str> = Vec::new();
    for segment in path.split('/') {
        match segment {
            "" | "." => {}
            ".." => {
                match parts.last() {
                    Some(&last) if last != ".." => {
                        parts.pop();
                    }
                    _ => {
                        if !absolute {
                            parts.push("..");
                        }
                    }
                };
            }
            other => parts.push(other),
        }
    }
    let mut result = parts.join("/");
    if result.is_empty() {
        return if absolute {
            "/".to_string()
        } else if trailing_slash {
            "./".to_string()
        } else {
            ".".to_string()
        };
    }
    if trailing_slash {
        result.push('/');
    }
    if absolute {
        format!("/{result}")
    } else {
        result
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn extname_matches_node() {
        assert_eq!(extname("a.js"), ".js");
        assert_eq!(extname("a.b.tsx"), ".tsx");
        assert_eq!(extname(".gitignore"), "");
        assert_eq!(extname("dir.d/file"), "");
        assert_eq!(extname("trailing."), ".");
        assert_eq!(extname("dir/"), "");
    }

    #[test]
    fn join_normalizes() {
        assert_eq!(join("a/", "b.js"), "a/b.js");
        assert_eq!(join("a", "b.js"), "a/b.js");
        assert_eq!(join("./a/", "b"), "a/b");
    }

    #[test]
    fn normalize_handles_traversal() {
        assert_eq!(normalize("/a/b/../c"), "/a/c");
        assert_eq!(normalize("../a"), "../a");
        assert_eq!(normalize("a//b"), "a/b");
    }
}
