{"command":"create","path":"/workspace/codebase/rust/src/colors.rs","file_text":"//! Port of `picocolors` including its color-support detection and nested-close
//! rewriting, so CLI output is identical to the JavaScript implementation.

use std::env;
use std::sync::OnceLock;

fn color_supported() -> bool {
    static SUPPORTED: OnceLock<bool> = OnceLock::new();
    *SUPPORTED.get_or_init(|| {
        let argv: Vec<String> = env::args().skip(1).collect();
        if env::var_os("NO_COLOR").is_some() || argv.iter().any(|a| a == "--no-color") {
            return false;
        }
        if env::var_os("FORCE_COLOR").is_some() || argv.iter().any(|a| a == "--color") {
            return true;
        }
        let isatty = unsafe { libc::isatty(1) } == 1;
        if isatty && env::var("TERM").map(|t| t != "dumb").unwrap_or(true) {
            return true;
        }
        env::var_os("CI").is_some()
    })
}

fn replace_close(input: &str, close: &str, replace: &str, mut index: usize) -> String {
    let mut result = String::new();
    let mut cursor = 0usize;
    loop {
        result.push_str(&input[cursor..index]);
        result.push_str(replace);
        cursor = index + close.len();
        match input[cursor..].find(close) {
            Some(next) => index = cursor + next,
            None => break,
        }
    }
    result.push_str(&input[cursor..]);
    result
}

fn format(open: &str, close: &str, replace: &str, input: &str) -> String {
    if !color_supported() {
        return input.to_string();
    }
    match input.get(open.len()..).and_then(|rest| {
        rest.find(close).map(|i| i + open.len())
    }) {
        Some(index) => format!("{open}{}{close}", replace_close(input, close, replace, index)),
        None => format!("{open}{input}{close}"),
    }
}

macro_rules! simple_color {
    ($name:ident, $open:expr, $close:expr) => {
        pub fn $name(input: &str) -> String {
            format($open, $close, $open, input)
        }
    };
}

simple_color!(red, "\x1b[31m", "\x1b[39m");
