{"command":"create","path":"/workspace/codebase/rust/src/args_parser.rs","file_text":"//! Port of `src/argsParser.js`.
//!
//! Option values are represented as `serde_json::Value` because unknown options
//! are parsed with JSON semantics, exactly like the JavaScript implementation.

use serde_json::{Map, Value};

pub type OptionMap = Map<String, Value>;

/// How the value of a recognized option is post-processed, mirroring the
/// `process` callbacks of the JavaScript option table.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Process {
    None,
    Number,
    JsonFile,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Callback {
    Help,
    Version,
}

#[derive(Clone)]
pub struct OptionSpec {
    pub key: &'static str,
    pub display_index: i32,
    pub abbr: Option<&'static str>,
    pub full: Option<&'static str>,
    pub flag: bool,
    pub list: bool,
    pub default: Option<Value>,
    pub default_help: Option<&'static str>,
    pub choices: Option<Vec<Value>>,
    pub help: Option<&'static str>,
    pub metavar: Option<&'static str>,
    pub process: Process,
    pub callback: Option<Callback>,
}

impl Default for OptionSpec {
    fn default() -> Self {
        OptionSpec {
            key: "",
            display_index: 0,
            abbr: None,
            full: None,
            flag: false,
            list: false,
            default: None,
            default_help: None,
            choices: None,
            help: None,
            metavar: None,
            process: Process::None,
            callback: None,
        }
    }
}

impl OptionSpec {
    pub fn full_name(&self) -> &str {
        self.full.unwrap_or(self.key)
    }
}

pub struct ParseError {
    pub exit_code: i32,
    pub message: String,
}

fn throw_error(exit_code: i32, message: String, help_text: Option<String>) -> ParseError {
    ParseError {
        exit_code,
        message: match help_text {
            Some(help) => format!("{message}\n\n---\n\n{help}"),
            None => message,
        },
    }
}

fn value_to_display(value: &Value) -> String {
    match value {
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

fn format_option(option: &OptionSpec) -> String {
    let mut text = String::from("  ");
    match option.abbr {
        Some(abbr) => text.push_str(&format!("-{abbr}, ")),
        None => text.push_str("    "),
    }
    text.push_str(&format!(
        "--{}{}",
        if option.flag { "(no-)" } else { "" },
        option.full_name()
    ));
    if let Some(choices) = &option.choices {
        let rendered: Vec<String> = choices.iter().map(value_to_display).collect();
        text.push_str(&format!("={}", rendered.join("|")));
    } else if let Some(metavar) = option.metavar {
        text.push_str(&format!("={metavar}"));
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.chars().count() < 32 {
            text.push_str(&" ".repeat(32 - text.chars().count()));
        }
        let text_length = text.chars().count();
        if let Some(help) = option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            let rendered = match option.default_help {
                Some(default_help) => default_help.to_string(),
                None => value_to_display(option.default.as_ref().unwrap()),
            };
            text.push_str(&format!("{}(default: {})", " ".repeat(text_length), rendered));
        }
    }
    text
}

pub fn get_help_text(options: &[OptionSpec]) -> String {
    let mut opts: Vec<&OptionSpec> = options.iter().collect();
    opts.sort_by_key(|option| option.display_index);
    let rendered: Vec<String> = opts.into_iter().map(format_option).collect();

    let text = format!(
        "
Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
\"...\" behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{}
",
        rendered.join("\n")
    );
    text.trim_start_matches([' ', '\t', '\n', '\r', '\u{b}', '\u{c}', '\u{a0}', '\u{feff}'])
        .to_string()
}

fn validate_options(
    parsed: &OptionMap,
    options: &[OptionSpec],
) -> Result<(), ParseError> {
    let mut errors = Vec::new();
    for option in options {
        if let Some(choices) = &option.choices {
            let current = parsed.get(option.key).unwrap_or(&Value::Null);
            if !choices.iter().any(|choice| choice == current) {
                let rendered: Vec<String> = choices.iter().map(value_to_display).collect();
                errors.push(format!(
                    "Error: --{} must be one of the values {}",
                    option.full_name(),
                    rendered.join(",")
                ));
            }
        }
    }
    if !errors.is_empty() {
        return Err(throw_error(
            1,
            errors.join("\n"),
            Some(get_help_text(options)),
        ));
    }
    Ok(())
}

fn is_option(value: &str) -> bool {
    value.starts_with('-')
}

fn is_option_opt(value: Option<&String>) -> bool {
    value.map(|v| is_option(v)).unwrap_or(false)
}

/// Values parsed with JSON semantics, falling back to the raw string, matching
/// the `process` implementation used for unknown options.
fn parse_json_like(value: &str) -> Value {
    serde_json::from_str(value).unwrap_or_else(|_| Value::String(value.to_string()))
}

pub struct ParseResult {
    pub options: OptionMap,
    pub positional_arguments: Vec<Value>,
}

/// A recognized or synthesized option, as produced by `prepareOptions` plus the
/// unknown-option fallback logic.
struct ResolvedOption<'a> {
    key: String,
    known: Option<&'a OptionSpec>,
    flag: bool,
    list: bool,
}

pub trait ProcessHooks {
    /// `process` implementation for `--parser-config`.
    fn read_json_file(&self, path: &str) -> Result<Value, String>;
    /// `callback` implementation for `--help` and `--version`.
    fn callback(&self, callback: Callback, options: &[OptionSpec]) -> String;
}

pub fn parse(
    options: &[OptionSpec],
    args: &[String],
    hooks: &dyn ProcessHooks,
) -> Result<ParseResult, ParseError> {
    let mut parsed: OptionMap = Map::new();
    let mut positional_arguments: Vec<Value> = Vec::new();
    // Tracks the keys whose value is still missing (the `missingValue` symbol).
    let mut missing: Vec<String> = Vec::new();

    for option in options {
        if let Some(default) = &option.default {
            parsed.insert(option.key.to_string(), default.clone());
        } else if option.list {
            parsed.insert(option.key.to_string(), Value::Array(Vec::new()));
        }
    }

    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if !is_option(arg) {
            let numeric = !arg.is_empty() && arg.bytes().all(|b| b.is_ascii_digit());
            positional_arguments.push(if numeric {
                parse_json_like(arg)
            } else {
                Value::String(arg.clone())
            });
            i += 1;
            continue;
        }

        let mut option_name = arg.clone();
        let mut value: Option<String> = None;
        if let Some(index) = arg.find('=') {
            option_name = arg[..index].to_string();
            value = Some(arg[index + 1..].to_string());
        }

        let known = options.iter().find(|option| {
            option_name == format!("--{}", option.full_name())
                || option
                    .abbr
                    .map(|abbr| option_name == format!("-{abbr}"))
                    .unwrap_or(false)
                || (option.flag && option_name == format!("--no-{}", option.full_name()))
        });

        let resolved = match known {
            Some(option) => ResolvedOption {
                key: option.key.to_string(),
                known: Some(option),
                flag: option.flag,
                list: option.list,
            },
            None => {
                let real_option_name = strip_option_prefix(&option_name);
                let is_list = parsed
                    .get(&real_option_name)
                    .map(|current| current != &Value::Bool(true))
                    .unwrap_or(false);
                let flag = !parsed.contains_key(&real_option_name)
                    && value.is_none()
                    && is_option_opt(args.get(i + 1));

                if is_list {
                    let current = parsed.get(&real_option_name).cloned().unwrap_or(Value::Null);
                    if !current.is_array() {
                        let replacement = if current == Value::Bool(true) {
                            Value::Array(Vec::new())
                        } else {
                            Value::Array(vec![current])
                        };
                        parsed.insert(real_option_name.clone(), replacement);
                    }
                }

                ResolvedOption {
                    key: real_option_name,
                    known: None,
                    flag,
                    list: is_list,
                }
            }
        };

        if let Some(callback) = resolved.known.and_then(|option| option.callback) {
            return Err(throw_error(0, hooks.callback(callback, options), None));
        }

        if resolved.flag {
            let flag_value = if option_name.starts_with("--no-") {
                false
            } else {
                match &value {
                    Some(raw) => raw == "1",
                    None => true,
                }
            };
            parsed.insert(resolved.key.clone(), Value::Bool(flag_value));
            missing.retain(|key| key != &resolved.key);
        } else {
            if value.is_none() && i < args.len() - 1 && !is_option_opt(args.get(i + 1)) {
                value = Some(args[i + 1].clone());
                i += 1;
            }
            match value {
                Some(raw) => {
                    let processed = match resolved.known {
                        Some(option) => match option.process {
                            Process::None => Value::String(raw),
                            Process::Number => to_number(&raw),
                            Process::JsonFile => match hooks.read_json_file(&raw) {
                                Ok(value) => value,
                                Err(message) => {
                                    return Err(ParseError {
                                        exit_code: 1,
                                        message,
                                    })
                                }
                            },
                        },
                        None => parse_json_like(&raw),
                    };
                    if resolved.list {
                        match parsed.get_mut(&resolved.key) {
                            Some(Value::Array(items)) => items.push(processed),
                            _ => {
                                parsed.insert(resolved.key.clone(), Value::Array(vec![processed]));
                            }
                        }
                    } else {
                        parsed.insert(resolved.key.clone(), processed);
                    }
                    missing.retain(|key| key != &resolved.key);
                }
                None => {
                    parsed.remove(&resolved.key);
                    parsed.insert(resolved.key.clone(), Value::Null);
                    if !missing.contains(&resolved.key) {
                        missing.push(resolved.key.clone());
                    }
                }
            }
        }
        i += 1;
    }

    if let Some(key) = missing.first() {
        // Unknown options never make it into the option table, which is why the
        // JavaScript implementation fails while reading `full` of `undefined`.
        return match options.iter().find(|option| option.key == key.as_str()) {
            Some(option) => Err(throw_error(
                1,
                format!(
                    "Missing value: --{} requires a value",
                    option.full_name()
                ),
                Some(get_help_text(options)),
            )),
            None => Err(ParseError {
                exit_code: 1,
                message: "Cannot read properties of undefined (reading 'full')".to_string(),
            }),
        };
    }

    validate_options(&parsed, options)?;

    Ok(ParseResult {
        options: parsed,
        positional_arguments,
    })
}

fn strip_option_prefix(option_name: &str) -> String {
    let without_dashes = option_name
        .strip_prefix("--")
        .or_else(|| option_name.strip_prefix('-'))
        .unwrap_or(option_name);
    without_dashes
        .strip_prefix("no-")
        .unwrap_or(without_dashes)
        .to_string()
}

/// JavaScript's `Number(value)` for the inputs the CLI can receive.
fn to_number(raw: &str) -> Value {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Value::from(0);
    }
    match trimmed.parse::<i64>() {
        Ok(int) => Value::from(int),
        Err(_) => match trimmed.parse::<f64>() {
            Ok(float) => serde_json::Number::from_f64(float)
                .map(Value::Number)
                .unwrap_or(Value::Null),
            // `NaN` has no JSON representation; `null` keeps choice validation
            // failing just like `NaN` does in JavaScript.
            Err(_) => Value::Null,
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct TestHooks;
    impl ProcessHooks for TestHooks {
        fn read_json_file(&self, _path: &str) -> Result<Value, String> {
            Ok(Value::Null)
        }
        fn callback(&self, _callback: Callback, _options: &[OptionSpec]) -> String {
            "callback".to_string()
        }
    }

    fn specs() -> Vec<OptionSpec> {
        vec![
            OptionSpec {
                key: "transform",
                abbr: Some("t"),
                default: Some(Value::String("./transform.js".to_string())),
                ..Default::default()
