use fancy_regex::Regex;
use std::collections::HashMap;
use std::sync::OnceLock;

const DOT_LITERAL: &str = "\\.";
const PLUS_LITERAL: &str = "\\+";
const SLASH_LITERAL: &str = "\\/";
const ONE_CHAR: &str = "(?=.)";
const QMARK: &str = "[^/]";
const END_ANCHOR: &str = "(?:\\/|$)";
const START_ANCHOR: &str = "(?:^|\\/)";
const DOTS_SLASH: &str = "\\.{1,2}(?:\\/|$)";
const NO_DOT: &str = "(?!\\.)";
const NO_DOTS: &str = "(?!(?:^|\\/)\\.{1,2}(?:\\/|$))";
const NO_DOT_SLASH: &str = "(?!\\.{0,1}(?:\\/|$))";
const NO_DOTS_SLASH: &str = "(?!\\.{1,2}(?:\\/|$))";
