const MAX_LENGTH: usize = 1024 * 64;

fn globstar() -> String {
    format!("(?:(?:(?!{START_ANCHOR}{DOTS_SLASH}).)*?)")
}

fn replacement(input: &str) -> &str {
    match input {
        "***" => "*",
        "**/**" | "**/**/**" => "**",
        other => other,
    }
}

fn is_regex_char(ch: char) -> bool {
    matches!(
        ch,
        '-' | '*' | '+' | '?' | '.' | '^' | '$' | '{' | '}' | '(' | '|' | ')' | '[' | ']'
    )
}

fn has_regex_chars(value: &str) -> bool {
    value.chars().any(is_regex_char)
}

fn escape_regex(value: &str) -> String {
    let mut result = String::with_capacity(value.len());
    for ch in value.chars() {
        if is_regex_char(ch) {
            result.push('\\');
        }
        result.push(ch);
    }
    result
}

/// `utils.escapeLast`: escapes the last occurrence of `ch` that is not itself
/// escaped.
fn escape_last(input: &str, ch: char) -> String {
    let chars: Vec<char> = input.chars().collect();
    let mut search_end = chars.len();
    loop {
        let idx = match chars[..search_end].iter().rposition(|c| *c == ch) {
            Some(idx) => idx,
            None => return input.to_string(),
        };
        if idx > 0 && chars[idx - 1] == '\\' {
            search_end = idx;
            continue;
        }
        let mut result: String = chars[..idx].iter().collect();
        result.push('\\');
        result.extend(chars[idx..].iter());
        return result;
    }
}

fn remove_prefix(input: &str) -> (String, String) {
    match input.strip_prefix("./") {
        Some(rest) => (rest.to_string(), "./".to_string()),
        None => (input.to_string(), String::new()),
    }
