fn wrap_output(input: &str, negated: bool) -> String {
    let output = format!("^(?:{input})$");
    if negated {
        format!("(?:^(?!{output}).*$)")
    } else {
        output
    }
}

#[derive(Clone, Default)]
struct Token {
    kind: String,
    value: String,
    output: Option<String>,
    prev: Option<usize>,
    star: bool,
    posix: bool,
    dots: bool,
    comma: bool,
    extglob: bool,
    output_index: usize,
    tokens_index: usize,
}

impl Token {
    fn new(kind: &str, value: &str) -> Token {
        Token {
            kind: kind.to_string(),
            value: value.to_string(),
            ..Default::default()
        }
    }

    fn with_output(kind: &str, value: &str, output: &str) -> Token {
        Token {
            kind: kind.to_string(),
            value: value.to_string(),
            output: Some(output.to_string()),
            ..Default::default()
        }
    }

    fn rendered(&self) -> &str {
        match &self.output {
            Some(output) => output,
            None => &self.value,
        }
    }
}

struct Extglob {
    kind: String,
    open: String,
    close: String,
    inner: String,
    parens: usize,
    prev: Option<usize>,
    #[allow(dead_code)]
    output: String,
}

fn extglob_chars(value: char) -> (&'static str, &'static str, &'static str) {
    match value {
        '!' => ("negate", "(?:(?!(?:", "))[^/]*?)"),
        '?' => ("qmark", "(?:", ")?"),
        '+' => ("plus", "(?:", ")+"),
        '*' => ("star", "(?:", ")*"),
        _ => ("at", "(?:", ")"),
    }
}

struct Parser {
    input: Vec<char>,
    index: isize,
    start: usize,
    consumed: String,
    output: String,
    backtrack: bool,
    negated: bool,
    brackets: isize,
    braces: isize,
    parens: isize,
    quotes: i32,
    globstar: bool,
    tokens: Vec<Token>,
    prev: usize,
    stack: Vec<String>,
    extglobs: Vec<Extglob>,
    braces_stack: Vec<usize>,
}

/// Result of parsing a glob: the regex source plus whether the glob was negated.
pub struct ParsedGlob {
    pub output: String,
    pub negated: bool,
}

impl Parser {
    fn new(input: &str) -> Parser {
        Parser {
            input: input.chars().collect(),
            index: -1,
            start: 0,
            consumed: String::new(),
            output: String::new(),
            backtrack: false,
            negated: false,
            brackets: 0,
            braces: 0,
            parens: 0,
            quotes: 0,
            globstar: false,
            tokens: vec![Token::with_output("bos", "", "")],
            prev: 0,
            stack: Vec::new(),
            extglobs: Vec::new(),
            braces_stack: Vec::new(),
        }
    }

    fn len(&self) -> isize {
        self.input.len() as isize
    }

    fn eos(&self) -> bool {
        self.index == self.len() - 1
    }

    fn peek(&self, n: isize) -> Option<char> {
        let idx = self.index + n;
        if idx < 0 {
            return None;
        }
        self.input.get(idx as usize).copied()
    }

    fn advance(&mut self) -> String {
        self.index += 1;
        match self.input.get(self.index as usize) {
            Some(ch) => ch.to_string(),
            None => String::new(),
        }
    }

    fn remaining(&self) -> String {
        let start = (self.index + 1).max(0) as usize;
        if start >= self.input.len() {
            return String::new();
        }
        self.input[start..].iter().collect()
    }

    fn consume(&mut self, value: &str, num: isize) {
        self.consumed.push_str(value);
        self.index += num;
    }

    fn append(&mut self, token: &Token) {
        self.output.push_str(token.rendered());
        let value = token.value.clone();
        self.consume(&value, 0);
    }

    fn increment(&mut self, kind: &str) {
        match kind {
            "parens" => self.parens += 1,
            "brackets" => self.brackets += 1,
            "braces" => self.braces += 1,
            _ => {}
        }
        self.stack.push(kind.to_string());
    }

    fn decrement(&mut self, kind: &str) {
        match kind {
            "parens" => self.parens -= 1,
            "brackets" => self.brackets -= 1,
            "braces" => self.braces -= 1,
            _ => {}
        }
        self.stack.pop();
    }

    fn push(&mut self, mut token: Token) {
        if self.tokens[self.prev].kind == "globstar" {
            let is_brace =
                self.braces > 0 && (token.kind == "comma" || token.kind == "brace");
            let is_extglob = token.extglob
                || (!self.extglobs.is_empty()
                    && (token.kind == "pipe" || token.kind == "paren"));

            if token.kind != "slash" && token.kind != "paren" && !is_brace && !is_extglob {
                let prev_output_len = self.tokens[self.prev].rendered().len();
                let keep = self.output.len().saturating_sub(prev_output_len);
                self.output.truncate(keep);
                let prev = &mut self.tokens[self.prev];
                prev.kind = "star".to_string();
                prev.value = "*".to_string();
                prev.output = Some(STAR.to_string());
                let rendered = prev.rendered().to_string();
                self.output.push_str(&rendered);
            }
        }

        if !self.extglobs.is_empty() && token.kind != "paren" {
            let value = token.value.clone();
            self.extglobs.last_mut().unwrap().inner.push_str(&value);
        }

        if !token.value.is_empty() || token.output.as_deref().map(|o| !o.is_empty()).unwrap_or(false)
        {
            let copy = token.clone();
            self.append(&copy);
        }

        if self.tokens[self.prev].kind == "text" && token.kind == "text" {
            let prev = &mut self.tokens[self.prev];
            let merged = format!("{}{}", prev.rendered(), token.value);
            prev.output = Some(merged);
            prev.value.push_str(&token.value);
            return;
        }

        token.prev = Some(self.prev);
        self.tokens.push(token);
        self.prev = self.tokens.len() - 1;
    }

    fn extglob_open(&mut self, kind: &str, value: char) {
        let (glob_kind, open, close) = extglob_chars(value);
        let token = Extglob {
            kind: glob_kind.to_string(),
            open: open.to_string(),
            close: close.to_string(),
            inner: String::new(),
            parens: self.parens as usize,
            prev: Some(self.prev),
            output: self.output.clone(),
        };
        let output = token.open.clone();

        self.increment("parens");
        let placeholder = if self.output.is_empty() { ONE_CHAR } else { "" };
        self.push(Token::with_output(kind, &value.to_string(), placeholder));
        let next = self.advance();
        let mut paren = Token::with_output("paren", &next, &output);
        paren.extglob = true;
        self.push(paren);
        self.extglobs.push(token);
    }

    fn extglob_close(&mut self, mut token: Extglob, value: &str) {
        let mut output = token.close.clone();

        if token.kind == "negate" {
            let mut extglob_star = STAR.to_string();

            if token.inner.chars().count() > 1 && token.inner.contains('/') {
                extglob_star = globstar();
            }

            let remaining = self.remaining();
            let only_parens = !remaining.is_empty() && remaining.chars().all(|c| c == ')');
            if extglob_star != STAR || self.eos() || only_parens {
                output = format!(")$)){extglob_star}");
                token.close = output.clone();
            }

            if token.inner.contains('*') && !remaining.is_empty() {
                if trailing_extension().is_match(&remaining).unwrap_or(false) {
                    let expression = parse(&remaining, false).output;
                    output = format!("){expression}){extglob_star})");
                    token.close = output.clone();
                }
            }
        }

        let mut paren = Token::with_output("paren", value, &output);
        paren.extglob = true;
        self.push(paren);
        self.decrement("parens");
    }
}

fn trailing_extension() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^\.[^\\/.]+$").unwrap())
}

fn non_special_chars_prefix(value: &str) -> String {
    let mut result = String::new();
    for ch in value.chars() {
        if matches!(
            ch,
            '@' | '!' | '[' | ']' | '.' | ',' | '$' | '*' | '+' | '?' | '^' | '{' | '}' | '('
                | ')' | '|' | '\\' | '/'
        ) {
            break;
        }
        result.push(ch);
    }
    result
}

/// Port of the `REGEX_SPECIAL_CHARS_BACKREF` replacement used by the parser's
/// fast path: it walks runs of a repeated non-word character, optionally
/// preceded by a backslash.
fn fastpath_replace(input: &str) -> (String, bool) {
    let chars: Vec<char> = input.chars().collect();
    let mut output = String::new();
    let mut backslashes = false;
    let mut i = 0usize;
    while i < chars.len() {
        let escaped = chars[i] == '\\' && i + 1 < chars.len() && !chars[i + 1].is_alphanumeric()
            && chars[i + 1] != '_';
        let (esc, first_index) = if escaped { ("\\", i + 1) } else { ("", i) };
        let first = chars[first_index];
        if first.is_alphanumeric() || first == '_' {
            output.push(chars[i]);
            i += 1;
            continue;
        }
        // `(\3*)`: the run of characters identical to `first` that follows it.
        let mut run_end = first_index + 1;
        while run_end < chars.len() && chars[run_end] == first {
            run_end += 1;
        }
        let rest_len = run_end - first_index - 1;
        let chars_len = run_end - first_index;
        let matched: String = chars[i..run_end].iter().collect();

        match first {
            '\\' => {
                backslashes = true;
                output.push_str(&matched);
            }
            '?' => {
                if !esc.is_empty() {
                    output.push_str(esc);
                    output.push(first);
                    output.push_str(&QMARK.repeat(rest_len));
                } else if i == 0 {
                    // `dot: true` makes `qmarkNoDot` equal to `QMARK`.
                    output.push_str(QMARK);
                    output.push_str(&QMARK.repeat(rest_len));
                } else {
                    output.push_str(&QMARK.repeat(chars_len));
                }
            }
            '.' => output.push_str(&DOT_LITERAL.repeat(chars_len)),
            '*' => {
                if !esc.is_empty() {
                    output.push_str(esc);
                    output.push(first);
                    if rest_len > 0 {
                        output.push_str(STAR);
                    }
                } else {
                    output.push_str(STAR);
                }
            }
            _ => {
                if !esc.is_empty() {
                    output.push_str(&matched);
                } else {
                    output.push('\\');
                    output.push_str(&matched);
                }
            }
        }
        i = run_end;
    }
    (output, backslashes)
}

fn collapse_backslashes(output: &str) -> String {
    let chars: Vec<char> = output.chars().collect();
    let mut result = String::new();
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] != '\\' {
            result.push(chars[i]);
            i += 1;
            continue;
        }
        let mut run = 0usize;
        while i + run < chars.len() && chars[i + run] == '\\' {
            run += 1;
        }
        result.push_str(if run % 2 == 0 { "\\\\" } else { "\\" });
        i += run;
    }
    result
}

fn parse(input: &str, allow_fastpaths: bool) -> ParsedGlob {
    let input = replacement(input);
    if input.chars().count() > MAX_LENGTH {
        return ParsedGlob {
            output: String::new(),
            negated: false,
        };
    }

    // Fast path for patterns without leading `*`/`!` and without structural
    // characters.
    if allow_fastpaths
        && !input.starts_with('*')
        && !input.starts_with('!')
        && !input.contains(['/', '(', ')', '[', ']', '{', '}', '"'])
    {
        let (mut output, backslashes) = fastpath_replace(input);
        if backslashes {
            output = collapse_backslashes(&output);
        }
        return ParsedGlob {
            output: wrap_output(&output, false),
            negated: false,
        };
    }

    let (stripped, _prefix) = remove_prefix(input);
    let mut state = Parser::new(&stripped);

    while !state.eos() {
        let mut value = state.advance();

        if value == "\u{0}" {
            continue;
        }

        if value == "\\" {
            let next = state.peek(1);
            if next == Some('/') {
                continue;
            }
            if next == Some('.') || next == Some(';') {
                continue;
            }
            if next.is_none() {
                value.push('\\');
                state.push(Token::new("text", &value));
                continue;
            }

            // Collapse slashes to reduce potential for exploits.
            let remaining = state.remaining();
            let leading_slashes = remaining.chars().take_while(|c| *c == '\\').count();
            if leading_slashes > 2 {
                state.index += leading_slashes as isize;
                if leading_slashes % 2 != 0 {
                    value.push('\\');
                }
            }

            let next_char = state.advance();
            value.push_str(&next_char);

            if state.brackets == 0 {
                state.push(Token::new("text", &value));
                continue;
            }
        }

        if state.brackets > 0
            && (value != "]"
                || state.tokens[state.prev].value == "["
                || state.tokens[state.prev].value == "[^")
        {
            if value == ":" {
                let inner: String = state.tokens[state.prev].value.chars().skip(1).collect();
                if inner.contains('[') {
                    state.tokens[state.prev].posix = true;
                    if inner.contains(':') {
                        let prev_value = state.tokens[state.prev].value.clone();
                        let idx = prev_value.rfind('[').unwrap();
                        let pre: String = prev_value[..idx].to_string();
                        let rest: String = prev_value.chars().skip(idx + 2).collect();
                        if let Some(posix) = posix_regex_source(&rest) {
                            state.tokens[state.prev].value = format!("{pre}{posix}");
                            state.backtrack = true;
                            state.advance();
                            if state.tokens[0].output.as_deref() == Some("") && state.prev == 1 {
                                state.tokens[0].output = Some(ONE_CHAR.to_string());
                            }
                            continue;
                        }
                    }
                }
            }

            if (value == "[" && state.peek(1) != Some(':'))
                || (value == "-" && state.peek(1) == Some(']'))
            {
                value = format!("\\{value}");
            }

            if value == "]"
                && (state.tokens[state.prev].value == "["
                    || state.tokens[state.prev].value == "[^")
            {
                value = format!("\\{value}");
            }

            state.tokens[state.prev].value.push_str(&value);
            let token = Token::new("", &value);
            state.append(&token);
            continue;
        }

        if state.quotes == 1 && value != "\"" {
            value = escape_regex(&value);
            state.tokens[state.prev].value.push_str(&value);
            let token = Token::new("", &value);
            state.append(&token);
            continue;
        }

        if value == "\"" {
            state.quotes = if state.quotes == 1 { 0 } else { 1 };
            continue;
        }

        if value == "(" {
            state.increment("parens");
            state.push(Token::new("paren", &value));
            continue;
        }

        if value == ")" {
            let close_extglob = state
                .extglobs
                .last()
                .map(|extglob| state.parens == extglob.parens as isize + 1)
                .unwrap_or(false);
            if close_extglob {
                let extglob = state.extglobs.pop().unwrap();
                state.extglob_close(extglob, &value);
                continue;
            }

            let output = if state.parens != 0 { ")" } else { "\\)" };
            state.push(Token::with_output("paren", &value, output));
            state.decrement("parens");
            continue;
        }

        if value == "[" {
            if !state.remaining().contains(']') {
                value = format!("\\{value}");
            } else {
                state.increment("brackets");
            }
            state.push(Token::new("bracket", &value));
            continue;
        }

        if value == "]" {
            if state.tokens[state.prev].kind == "bracket"
                && state.tokens[state.prev].value.chars().count() == 1
            {
                state.push(Token::with_output("text", &value, "\\]"));
                continue;
            }

            if state.brackets == 0 {
                state.push(Token::with_output("text", &value, "\\]"));
                continue;
            }

            state.decrement("brackets");

            let prev_value: String = state.tokens[state.prev].value.chars().skip(1).collect();
            if !state.tokens[state.prev].posix
                && prev_value.starts_with('^')
                && !prev_value.contains('/')
            {
                value = format!("/{value}");
            }

            state.tokens[state.prev].value.push_str(&value);
            let token = Token::new("", &value);
            state.append(&token);

            if has_regex_chars(&prev_value) {
                continue;
            }

            let escaped = escape_regex(&state.tokens[state.prev].value);
            let keep = state
                .output
                .len()
                .saturating_sub(state.tokens[state.prev].value.len());
            state.output.truncate(keep);

            let combined = format!("(?:{escaped}|{})", state.tokens[state.prev].value);
            state.tokens[state.prev].value = combined.clone();
            state.output.push_str(&combined);
            continue;
        }

        if value == "{" {
            state.increment("braces");
            let mut open = Token::with_output("brace", &value, "(");
            open.output_index = state.output.len();
            open.tokens_index = state.tokens.len();
            state.push(open);
            state.braces_stack.push(state.prev);
            continue;
        }

        if value == "}" {
            let brace_index = match state.braces_stack.last().copied() {
                Some(index) => index,
                None => {
                    state.push(Token::with_output("text", &value, &value));
                    continue;
                }
            };

            let mut output = ")".to_string();

            if state.tokens[brace_index].dots {
                let arr = state.tokens.clone();
                let mut range: Vec<String> = Vec::new();
                for i in (0..arr.len()).rev() {
                    state.tokens.pop();
                    if arr[i].kind == "brace" {
                        break;
                    }
                    if arr[i].kind != "dots" {
                        range.insert(0, arr[i].value.clone());
                    }
                }
                output = expand_range(&range);
                state.backtrack = true;
                state.prev = state.tokens.len().saturating_sub(1);
            }

            if !state.tokens[brace_index].comma && !state.tokens[brace_index].dots {
                let out: String = state.output[..state.tokens[brace_index].output_index].to_string();
                let toks: Vec<Token> = state.tokens[state.tokens[brace_index].tokens_index..]
                    .to_vec();
                state.tokens[brace_index].value = "\\{".to_string();
                state.tokens[brace_index].output = Some("\\{".to_string());
                value = "\\}".to_string();
                output = "\\}".to_string();
                state.output = out;
                for token in &toks {
                    state.output.push_str(token.rendered());
                }
            }

            state.push(Token::with_output("brace", &value, &output));
            state.decrement("braces");
            state.braces_stack.pop();
            continue;
        }

        if value == "|" {
            state.push(Token::new("text", &value));
            continue;
        }

        if value == "," {
            let mut output = value.clone();
            if let Some(&brace_index) = state.braces_stack.last() {
                if state.stack.last().map(|s| s.as_str()) == Some("braces") {
                    state.tokens[brace_index].comma = true;
                    output = "|".to_string();
                }
            }
            state.push(Token::with_output("comma", &value, &output));
            continue;
        }

        if value == "/" {
            if state.tokens[state.prev].kind == "dot"
                && state.index == state.start as isize + 1
            {
                state.start = (state.index + 1) as usize;
                state.consumed = String::new();
                state.output = String::new();
                state.tokens.pop();
                state.prev = 0;
                continue;
            }
            state.push(Token::with_output("slash", &value, SLASH_LITERAL));
            continue;
        }

        if value == "." {
            if state.braces > 0 && state.tokens[state.prev].kind == "dot" {
                if state.tokens[state.prev].value == "." {
                    state.tokens[state.prev].output = Some(DOT_LITERAL.to_string());
                }
                let brace_index = *state.braces_stack.last().unwrap();
                let prev = &mut state.tokens[state.prev];
                prev.kind = "dots".to_string();
                let output = format!("{}{}", prev.rendered(), value);
                prev.output = Some(output);
                prev.value.push_str(&value);
                state.tokens[brace_index].dots = true;
                continue;
            }

            if state.braces + state.parens == 0
                && state.tokens[state.prev].kind != "bos"
                && state.tokens[state.prev].kind != "slash"
            {
                state.push(Token::with_output("text", &value, DOT_LITERAL));
                continue;
            }

            state.push(Token::with_output("dot", &value, DOT_LITERAL));
            continue;
        }

        if value == "?" {
            let is_group = state.tokens[state.prev].value == "(";
            if !is_group && state.peek(1) == Some('(') && state.peek(2) != Some('?') {
                state.extglob_open("qmark", '?');
                continue;
            }

            if state.tokens[state.prev].kind == "paren" {
                let next = state.peek(1);
                let mut output = value.clone();
                let next_is_special = matches!(next, Some('!') | Some('=') | Some('<') | Some(':'));
                let lookbehind = next == Some('<')
                    && !lookbehind_pattern().is_match(&state.remaining()).unwrap_or(false);
                if (state.tokens[state.prev].value == "(" && !next_is_special) || lookbehind {
                    output = format!("\\{value}");
                }
                state.push(Token::with_output("text", &value, &output));
                continue;
            }

            // `dot: true` keeps the plain `QMARK` output even at the start of a
            // segment.
            state.push(Token::with_output("qmark", &value, QMARK));
            continue;
        }

        if value == "!" {
            if state.peek(1) == Some('(')
                && (state.peek(2) != Some('?')
                    || !matches!(state.peek(3), Some('!') | Some('=') | Some('<') | Some(':')))
            {
                state.extglob_open("negate", '!');
                continue;
            }

            if state.index == 0 {
                let mut count = 1;
                while state.peek(1) == Some('!')
                    && (state.peek(2) != Some('(') || state.peek(3) == Some('?'))
                {
                    state.advance();
                    state.start += 1;
                    count += 1;
                }
                if count % 2 != 0 {
                    state.negated = true;
                    state.start += 1;
                }
                continue;
            }
        }

        if value == "+" {
            if state.peek(1) == Some('(') && state.peek(2) != Some('?') {
                state.extglob_open("plus", '+');
                continue;
            }

            if state.tokens[state.prev].value == "(" {
                state.push(Token::with_output("plus", &value, PLUS_LITERAL));
                continue;
            }

            let prev_kind = state.tokens[state.prev].kind.clone();
            if prev_kind == "bracket" || prev_kind == "paren" || prev_kind == "brace"
                || state.parens > 0
            {
                state.push(Token::new("plus", &value));
                continue;
            }

            state.push(Token::new("plus", PLUS_LITERAL));
            continue;
        }

        if value == "@" {
            if state.peek(1) == Some('(') && state.peek(2) != Some('?') {
                let mut token = Token::with_output("at", &value, "");
                token.extglob = true;
                state.push(token);
                continue;
            }
            state.push(Token::new("text", &value));
            continue;
        }

        if value != "*" {
            if value == "$" || value == "^" {
                value = format!("\\{value}");
            }
            let matched = non_special_chars_prefix(&state.remaining());
            if !matched.is_empty() {
                value.push_str(&matched);
                state.index += matched.chars().count() as isize;
            }
            state.push(Token::new("text", &value));
            continue;
        }

        if state.tokens[state.prev].kind == "globstar" || state.tokens[state.prev].star {
            let prev = &mut state.tokens[state.prev];
            prev.kind = "star".to_string();
            prev.star = true;
            prev.value.push_str(&value);
            prev.output = Some(STAR.to_string());
            state.backtrack = true;
            state.globstar = true;
            state.consume(&value.clone(), 0);
            continue;
        }

        let mut rest = state.remaining();
        if rest.starts_with('(') && !rest[1..].starts_with('?') && rest.chars().count() > 1 {
            state.extglob_open("star", '*');
            continue;
        }

        if state.tokens[state.prev].kind == "star" {
            let prior = state.tokens[state.prev].prev.unwrap();
            let before = state.tokens[prior].prev;
            let is_start =
                state.tokens[prior].kind == "slash" || state.tokens[prior].kind == "bos";
            let after_star = before
                .map(|index| {
                    state.tokens[index].kind == "star" || state.tokens[index].kind == "globstar"
                })
                .unwrap_or(false);

            let is_brace = state.braces > 0
                && (state.tokens[prior].kind == "comma" || state.tokens[prior].kind == "brace");
            let is_extglob = !state.extglobs.is_empty()
                && (state.tokens[prior].kind == "pipe" || state.tokens[prior].kind == "paren");
            if !is_start && state.tokens[prior].kind != "paren" && !is_brace && !is_extglob {
                state.push(Token::with_output("star", &value, ""));
                continue;
            }

            // Strip consecutive `/**/`.
            while rest.starts_with("/**") {
                let after = state.input.get((state.index + 4) as usize).copied();
                if let Some(after) = after {
                    if after != '/' {
                        break;
                    }
                }
                rest = rest.chars().skip(3).collect();
                state.consume("/**", 3);
            }

            if state.tokens[prior].kind == "bos" && state.eos() {
                let output = globstar();
                let prev = &mut state.tokens[state.prev];
                prev.kind = "globstar".to_string();
                prev.value.push_str(&value);
                prev.output = Some(output.clone());
                state.output = output;
                state.globstar = true;
                state.consume(&value.clone(), 0);
                continue;
            }

            let prior_prev_kind = state.tokens[state.tokens[prior].prev.unwrap_or(0)]
                .kind
                .clone();

            if state.tokens[prior].kind == "slash"
                && prior_prev_kind != "bos"
                && !after_star
                && state.eos()
            {
                let combined_len = state.tokens[prior].rendered().len()
                    + state.tokens[state.prev].rendered().len();
                let keep = state.output.len().saturating_sub(combined_len);
                state.output.truncate(keep);
                let prior_output = format!("(?:{}", state.tokens[prior].rendered());
                state.tokens[prior].output = Some(prior_output.clone());

                let prev_output = format!("{}|$)", globstar());
                let prev = &mut state.tokens[state.prev];
                prev.kind = "globstar".to_string();
                prev.output = Some(prev_output.clone());
                prev.value.push_str(&value);
                state.globstar = true;
                state.output.push_str(&prior_output);
                state.output.push_str(&prev_output);
                state.consume(&value.clone(), 0);
                continue;
            }

            if state.tokens[prior].kind == "slash"
                && prior_prev_kind != "bos"
                && rest.starts_with('/')
            {
                let end = if rest.chars().nth(1).is_some() { "|$" } else { "" };

                let combined_len = state.tokens[prior].rendered().len()
                    + state.tokens[state.prev].rendered().len();
                let keep = state.output.len().saturating_sub(combined_len);
                state.output.truncate(keep);
                let prior_output = format!("(?:{}", state.tokens[prior].rendered());
                state.tokens[prior].output = Some(prior_output.clone());

                let prev_output = format!(
                    "{}{SLASH_LITERAL}|{SLASH_LITERAL}{end})",
                    globstar()
                );
                let prev = &mut state.tokens[state.prev];
                prev.kind = "globstar".to_string();
                prev.output = Some(prev_output.clone());
                prev.value.push_str(&value);

                state.output.push_str(&prior_output);
                state.output.push_str(&prev_output);
                state.globstar = true;

                let next = state.advance();
                state.consume(&format!("{value}{next}"), 0);

                state.push(Token::with_output("slash", "/", ""));
                continue;
            }

            if state.tokens[prior].kind == "bos" && rest.starts_with('/') {
                let output = format!(
                    "(?:^|{SLASH_LITERAL}|{}{SLASH_LITERAL})",
                    globstar()
                );
                let prev = &mut state.tokens[state.prev];
                prev.kind = "globstar".to_string();
                prev.value.push_str(&value);
                prev.output = Some(output.clone());
                state.output = output;
                state.globstar = true;
                let next = state.advance();
                state.consume(&format!("{value}{next}"), 0);
                state.push(Token::with_output("slash", "/", ""));
                continue;
            }

            let keep = state
                .output
                .len()
                .saturating_sub(state.tokens[state.prev].rendered().len());
            state.output.truncate(keep);

            let output = globstar();
            let prev = &mut state.tokens[state.prev];
            prev.kind = "globstar".to_string();
            prev.output = Some(output.clone());
            prev.value.push_str(&value);

            state.output.push_str(&output);
            state.globstar = true;
            state.consume(&value.clone(), 0);
            continue;
        }

        let mut token = Token::with_output("star", &value, STAR);

        if state.index == state.start as isize
            || state.tokens[state.prev].kind == "slash"
            || state.tokens[state.prev].kind == "dot"
        {
            let addition = if state.tokens[state.prev].kind == "dot" {
                NO_DOT_SLASH
            } else {
                // `dot: true`
                NO_DOTS_SLASH
            };
            state.output.push_str(addition);
            let prev_output = format!("{}{addition}", state.tokens[state.prev].rendered());
            state.tokens[state.prev].output = Some(prev_output);

            if state.peek(1) != Some('*') {
                state.output.push_str(ONE_CHAR);
                let prev_output = format!("{}{ONE_CHAR}", state.tokens[state.prev].rendered());
                state.tokens[state.prev].output = Some(prev_output);
            }
        }

        token.output = Some(STAR.to_string());
        state.push(token);
    }

    while state.brackets > 0 {
        state.output = escape_last(&state.output, '[');
        state.decrement("brackets");
    }

    while state.parens > 0 {
        state.output = escape_last(&state.output, '(');
        state.decrement("parens");
    }

    while state.braces > 0 {
        state.output = escape_last(&state.output, '{');
        state.decrement("braces");
    }

    if state.tokens[state.prev].kind == "star" || state.tokens[state.prev].kind == "bracket" {
        state.push(Token::with_output(
            "maybe_slash",
            "",
            &format!("{SLASH_LITERAL}?"),
        ));
    }

    if state.backtrack {
        state.output = String::new();
        let rendered: Vec<String> = state
            .tokens
            .iter()
            .map(|token| token.rendered().to_string())
            .collect();
        for chunk in rendered {
            state.output.push_str(&chunk);
        }
    }

    ParsedGlob {
        output: state.output,
        negated: state.negated,
    }
}

fn lookbehind_pattern() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"<([!=]|\w+>)").unwrap())
}

fn posix_regex_source(name: &str) -> Option<&'static str> {
    Some(match name {
        "alnum" => "a-zA-Z0-9",
        "alpha" => "a-zA-Z",
        "ascii" => "\\x00-\\x7F",
        "blank" => " \\t",
        "cntrl" => "\\x00-\\x1F\\x7F",
        "digit" => "0-9",
        "graph" => "\\x21-\\x7E",
        "lower" => "a-z",
        "print" => "\\x20-\\x7E ",
        "punct" => "\\-!\"#$%&'()\\*+,./:;<=>?@[\\]^_`{|}~",
        "space" => " \\t\\r\\n\\v\\f",
        "upper" => "A-Z",
        "word" => "A-Za-z0-9_",
        "xdigit" => "A-Fa-f0-9",
        _ => return None,
    })
}

fn expand_range(args: &[String]) -> String {
    let mut sorted: Vec<String> = args.to_vec();
    sorted.sort();
    format!("[{}]", sorted.join("-"))
}

/// Port of `parse.fastpaths`, used by `makeRe` for patterns starting with `.`
/// or `*`.
fn fastpaths(input: &str) -> Option<String> {
    let input = replacement(input);
    let (output, _prefix) = remove_prefix(input);

    fn create(value: &str) -> Option<String> {
        // `dot: true`
        let nodot = NO_DOTS;
        let slash_dot = NO_DOTS_SLASH;
        Some(match value {
            "*" => format!("{nodot}{ONE_CHAR}{STAR}"),
            ".*" => format!("{DOT_LITERAL}{ONE_CHAR}{STAR}"),
            "*.*" => format!("{nodot}{STAR}{DOT_LITERAL}{ONE_CHAR}{STAR}"),
            "*/*" => format!("{nodot}{STAR}{SLASH_LITERAL}{ONE_CHAR}{slash_dot}{STAR}"),
            "**" => format!("{nodot}{}", globstar()),
            "**/*" => format!(
                "(?:{nodot}{}{SLASH_LITERAL})?{slash_dot}{ONE_CHAR}{STAR}",
                globstar()
            ),
            "**/*.*" => format!(
                "(?:{nodot}{}{SLASH_LITERAL})?{slash_dot}{STAR}{DOT_LITERAL}{ONE_CHAR}{STAR}",
                globstar()
            ),
            "**/.*" => format!(
                "(?:{nodot}{}{SLASH_LITERAL})?{DOT_LITERAL}{ONE_CHAR}{STAR}",
                globstar()
            ),
            other => {
                let (head, extension) = split_extension(other)?;
                let source = create(&head)?;
                format!("{source}{DOT_LITERAL}{extension}")
            }
        })
    }

    let mut source = create(&output)?;
    source.push_str(&format!("{SLASH_LITERAL}?"));
    Some(source)
}

/// `/^(.*?)\.(\w+)$/`
fn split_extension(value: &str) -> Option<(String, String)> {
    let chars: Vec<char> = value.chars().collect();
    for i in 0..chars.len() {
        if chars[i] != '.' {
            continue;
        }
        let rest = &chars[i + 1..];
        if !rest.is_empty() && rest.iter().all(|c| c.is_alphanumeric() || *c == '_') {
            return Some((chars[..i].iter().collect(), rest.iter().collect()));
        }
    }
    None
}

fn make_re(pattern: &str) -> Option<Regex> {
    if pattern.is_empty() {
        return None;
    }

    let mut parsed: Option<ParsedGlob> = None;
    if pattern.starts_with('.') || pattern.starts_with('*') {
        if let Some(output) = fastpaths(pattern) {
            parsed = Some(ParsedGlob {
                output,
                negated: false,
            });
        }
    }
    let parsed = parsed.unwrap_or_else(|| parse(pattern, true));

    let mut source = format!("^(?:{})$", parsed.output);
    if parsed.negated {
        source = format!("^(?!{source}).*$");
    }
    Regex::new(&source).ok()
}

/// Compiled matcher cache keyed by the glob source, mirroring how the
/// JavaScript implementation compiles each pattern once per matcher list.
pub struct Matchers {
    patterns: Vec<String>,
    regexes: Vec<Option<Regex>>,
}

impl Matchers {
    pub fn new(patterns: &[String]) -> Matchers {
        let mut cache: HashMap<&str, Option<Regex>> = HashMap::new();
        let mut regexes = Vec::with_capacity(patterns.len());
        for pattern in patterns {
            let entry = cache
                .entry(pattern.as_str())
                .or_insert_with(|| make_re(pattern));
            regexes.push(entry.clone());
        }
        Matchers {
            patterns: patterns.to_vec(),
            regexes,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.patterns.is_empty()
    }

    /// `picomatch.isMatch(path, patterns, { dot: true })`
    pub fn is_match(&self, input: &str) -> bool {
        if input.is_empty() {
            return false;
        }
        for (pattern, regex) in self.patterns.iter().zip(self.regexes.iter()) {
            if input == pattern {
                return true;
            }
            if let Some(regex) = regex {
                if regex.is_match(input).unwrap_or(false) {
                    return true;
                }
            }
        }
        false
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn matches(pattern: &str, path: &str) -> bool {
        Matchers::new(&[pattern.to_string()]).is_match(path)
    }

    #[test]
    fn matches_globstar_patterns() {
        assert!(matches("**/node_modules", "node_modules"));
        assert!(matches("**/node_modules", "a/b/node_modules"));
        assert!(matches("**/node_modules/**", "a/node_modules/b/c.js"));
        assert!(matches("**/node_modules/**", "node_modules/c.js"));
        assert!(!matches("**/node_modules/**", "a/nm/c.js"));
    }

    #[test]
    fn matches_dotfiles_because_dot_option_is_set() {
        assert!(matches("**/*", ".dotfile"));
        assert!(matches("**/.hidden/**", "a/.hidden/b.js"));
    }

    #[test]
    fn star_does_not_cross_separators() {
        assert!(matches("*.js", "a.js"));
        assert!(!matches("*.js", "a/b.js"));
        assert!(matches("**/*.js", "a/b.js"));
        assert!(matches("**/*.js", "b.js"));
    }

    #[test]
    fn supports_braces_and_directories() {
        assert!(matches("{a,b}/*.js", "a/x.js"));
        assert!(matches("src/**", "src"));
        assert!(matches("src/**", "src/a/b.js"));
        assert!(matches("a/**/b", "a/b"));
        assert!(matches("a/**/b", "a/x/y/b"));
    }

    #[test]
    fn literal_equality_short_circuits() {
        assert!(matches("node_modules/", "node_modules/"));
        assert!(!matches("node_modules/", "node_modules/x"));
    }

    #[test]
    fn leading_dot_slash_is_not_matched_by_globstar() {
        assert!(!matches("**/build", "./build"));
    }
}
