use crate::glob::Matchers;
use serde_json::Value;
use std::fs;

#[derive(Default)]
pub struct IgnoreFiles {
    patterns: Vec<String>,
    matchers: Option<Matchers>,
}

impl IgnoreFiles {
    pub fn new() -> IgnoreFiles {
        IgnoreFiles::default()
    }

    /// Add glob patterns to ignore matched files and folders. Creates glob
    /// patterns to approximate gitignore patterns.
    fn add_ignore_pattern(&mut self, value: &str) {
        if value.is_empty() || value.starts_with('#') {
            return;
        }
        let pattern = value;
        if !pattern.contains('/') {
            self.patterns.push(format!("**/{pattern}"));
        } else if pattern.ends_with('/') {
            self.patterns.push(format!("**/{pattern}**"));
            self.patterns.push(format!("{pattern}**"));
        }
        self.patterns.push(pattern.to_string());
        self.matchers = None;
    }

    /// Adds ignore patterns directly from the parsed option value, which may be
    /// a single string or a list of strings.
    pub fn add(&mut self, input: Option<&Value>) {
        for pattern in flatten_strings(input) {
            self.add_ignore_pattern(&pattern);
        }
    }

    /// Adds ignore patterns by reading files.
    pub fn add_from_file(&mut self, input: Option<&Value>) -> Result<(), String> {
        let mut lines: Vec<String> = Vec::new();
        for config in flatten_strings(input) {
            let metadata = fs::metadata(&config)
                .map_err(|error| format_stat_error(&config, &error))?;
            if metadata.is_file() {
                let content = fs::read_to_string(&config)
                    .map_err(|error| format!("Error: {error}"))?;
                lines.extend(split_lines(&content));
            }
        }
        for line in lines {
            self.add_ignore_pattern(&line);
        }
        Ok(())
    }

    pub fn should_ignore(&mut self, path: &str) -> bool {
        if self.patterns.is_empty() {
            return false;
        }
        if self.matchers.is_none() {
            self.matchers = Some(Matchers::new(&self.patterns));
        }
        let matchers = self.matchers.as_ref().unwrap();
        if matchers.is_empty() {
            return false;
        }
        // Files discovered from a relative source path (e.g. `../src` or
        // `./src`) are enumerated with a leading `../` or `./` traversal
        // prefix, which `**` does not match across. Also match the path with
        // any leading traversal prefix stripped so ignore behavior is
        // consistent regardless of how the source path was specified.
        // See https://github.com/facebook/jscodeshift/issues/556
        let normalized = strip_traversal_prefix(path);
        matchers.is_match(path) || (normalized != path && matchers.is_match(&normalized))
    }
}

/// `/^(?:\.\.?[/\\])+/`
fn strip_traversal_prefix(path: &str) -> String {
    let bytes = path.as_bytes();
    let mut index = 0usize;
    loop {
        let rest = &bytes[index..];
        if rest.starts_with(b"../") || rest.starts_with(b"..\\") {
            index += 3;
        } else if rest.starts_with(b"./") || rest.starts_with(b".\\") {
            index += 2;
        } else {
            break;
        }
    }
    path[index..].to_string()
}

/// `/\r?\n/`
fn split_lines(content: &str) -> Vec<String> {
    content
        .split('\n')
        .map(|line| line.strip_suffix('\r').unwrap_or(line).to_string())
        .collect()
}

/// Mirrors `[].concat(input)` followed by the string check in
/// `addIgnorePattern`: non-string entries are silently dropped.
fn flatten_strings(input: Option<&Value>) -> Vec<String> {
    match input {
        None | Some(Value::Null) => Vec::new(),
        Some(Value::String(value)) => vec![value.clone()],
        Some(Value::Array(values)) => values
            .iter()
            .filter_map(|value| value.as_str().map(|s| s.to_string()))
            .collect(),
        Some(_) => Vec::new(),
    }
}

fn format_stat_error(path: &str, error: &std::io::Error) -> String {
    match error.kind() {
        std::io::ErrorKind::NotFound => format!(
            "Error: ENOENT: no such file or directory, stat '{path}'"
        ),
        _ => format!("Error: {error}, stat '{path}'"),
    }
}

