 * batches arrive on stdin, notifications are written to file descriptor 3 so
 * that anything the transform prints on stdout/stderr is passed through
 * unchanged.
 */

'use strict';

const async = require('neo-async');
const fs = require('fs');
const { DEFAULT_EXTENSIONS } = require('@babel/core');
const getParser = require('./getParser');

const jscodeshift = require('./core');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

const NOTIFY_FD = 3;

let transform;
let parserFromTransform;

function notify(data) {
  fs.writeSync(NOTIFY_FD, JSON.stringify(data) + '\n');
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        {targets: {node: true}},
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr) ?
        require('@babel/preset-typescript').default :
        require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      // By default, babel register only compiles things inside the current working directory.
      // https://github.com/babel/babel/blob/2a4f16236656178e84b05b8915aab9261c55782c/packages/babel-register/src/node.js#L140-L157
      ignore: [
        // Ignore parser related files
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function' ?
    module.default :
    module;
  if (module.parser) {
    parserFromTransform = typeof module.parser === 'string' ?
      getParser(module.parser) :
      module.parser;
  }
}

function free() {
  notify({action: 'free'});
}

function report(file, msg) {
  notify({action: 'report', file, msg});
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  notify({action: 'update', name: name, quantity: quantity});
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  // Remove this file from the stack trace of an error thrown in the transformer
  const lines = trace.split('\n');
  const result = [];
  lines.every(function(line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files.length) {
    finish();
    return;
  }
  async.each(
    files,
    function(file, callback) {
      const source = file.source;
      (async function() {
        try {
          const jscodeshift = prepareJscodeshift(options);
          const out = await transform(
            {
              path: file.path,
              source: source,
            },
            {
              j: jscodeshift,
              jscodeshift: jscodeshift,
              stats: options.dry ? stats : empty,
              report: msg => report(file.path, msg),
            },
            options
          );
          notify({
            action: 'transformed',
            file: file.path,
            out: out === undefined ? null : out,
          });
          callback();
        } catch(err) {
          notify({
            action: 'error',
            file: file.path,
            msg: 'Transformation error ('+ err.message.replace(/\n/g, ' ') + ')\n' +
              trimStackTrace(err.stack),
          });
          callback();
        }
      })();
    },
    function() {
      free();
    }
  );
}

let buffer = '';
function onData(data) {
  buffer += data;
  let index;
  while ((index = buffer.indexOf('\n')) !== -1) {
    const line = buffer.slice(0, index);
    buffer = buffer.slice(index + 1);
    if (line) {
      run(JSON.parse(line));
    }
  }
}

function finish() {
  // Removing the only remaining handle lets the process exit naturally once
  // pending writes have been flushed.
  process.stdin.removeListener('data', onData);
  process.stdin.pause();
}

setup(process.argv[2], process.argv[3]);
process.stdin.setEncoding('utf8');
process.stdin.on('data', onData);
