{"command":"create","path":"/workspace/codebase/rust/src/write_file_atomic.rs","file_text":"//! Port of the `write-file-atomic` behavior used when persisting transformed
//! sources: write to a sibling temporary file, preserve mode and ownership of
//! the original file, fsync and rename into place.

use std::fs::{self, File, OpenOptions};
use std::io::Write;
use std::os::unix::fs::OpenOptionsExt;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, Ordering};

static INVOCATIONS: AtomicU32 = AtomicU32::new(0);

/// `imurmurhash` based suffix of `write-file-atomic`, seeded like the original
/// with the module path, pid, thread id and invocation counter.
fn tmp_name(filename: &Path) -> PathBuf {
    let invocation = INVOCATIONS.fetch_add(1, Ordering::SeqCst) + 1;
    let mut hash = ImurmurHash::new();
    hash.hash(module!());
    hash.hash(&std::process::id().to_string());
    hash.hash("0");
    hash.hash(&invocation.to_string());
    let mut name = filename.as_os_str().to_os_string();
    name.push(format!(".{}", hash.result()));
    PathBuf::from(name)
}

fn module() -> &'static str {
    "write-file-atomic"
}

macro_rules! module {
    () => {
        module()
    };
}

pub fn write_file_atomic(filename: &str, data: &str) -> Result<(), String> {
    let path = Path::new(filename);
    let truename = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    let tmpfile = tmp_name(&truename);

    let metadata = fs::metadata(&truename).ok();
    let mode = metadata.as_ref().map(|meta| meta.mode() & 0o7777);
    let owner = metadata.as_ref().map(|meta| (meta.uid(), meta.gid()));

    let result = (|| -> std::io::Result<()> {
        let mut options = OpenOptions::new();
        options.write(true).create(true).truncate(true);
        if let Some(mode) = mode {
            options.mode(mode);
        }
        let mut file: File = options.open(&tmpfile)?;
        file.write_all(data.as_bytes())?;
        file.sync_all()?;
        drop(file);

        if let Some((uid, gid)) = owner {
            chown(&tmpfile, uid, gid)?;
        }
        if let Some(mode) = mode {
            fs::set_permissions(&tmpfile, std::os::unix::fs::PermissionsExt::from_mode(mode))?;
        }
        fs::rename(&tmpfile, &truename)?;
        Ok(())
    })();

    match result {
        Ok(()) => Ok(()),
        Err(error) => {
            let _ = fs::remove_file(&tmpfile);
            Err(format_error(&error, &tmpfile))
        }
    }
}

fn chown(path: &Path, uid: u32, gid: u32) -> std::io::Result<()> {
    let c_path = std::ffi::CString::new(path.as_os_str().as_encoded_bytes())
        .map_err(|_| std::io::Error::from(std::io::ErrorKind::InvalidInput))?;
    let status = unsafe { libc::chown(c_path.as_ptr(), uid, gid) };
    if status == 0 {
        return Ok(());
    }
    let error = std::io::Error::last_os_error();
    // `isChownErrOk`: unprivileged processes may not be able to change the
    // owner, which the JavaScript implementation tolerates.
    let code = error.raw_os_error().unwrap_or(0);
    let nonroot = unsafe { libc::getuid() } != 0;
    if code == libc::ENOSYS || (nonroot && (code == libc::EINVAL || code == libc::EPERM)) {
        return Ok(());
    }
    Err(error)
}

/// Formats an `io::Error` like the `Error` objects Node passes to the
/// `writeFileAtomic` callback, which the runner interpolates into its output.
fn format_error(error: &std::io::Error, path: &Path) -> String {
    let code = match error.raw_os_error() {
        Some(libc::ENOENT) => "ENOENT",
        Some(libc::EACCES) => "EACCES",
        Some(libc::EPERM) => "EPERM",
        Some(libc::EISDIR) => "EISDIR",
        Some(libc::ENOSPC) => "ENOSPC",
        Some(libc::EROFS) => "EROFS",
        _ => "",
    };
    let description = match error.raw_os_error() {
        Some(libc::ENOENT) => "no such file or directory",
        Some(libc::EACCES) => "permission denied",
        Some(libc::EPERM) => "operation not permitted",
        Some(libc::EISDIR) => "illegal operation on a directory",
        Some(libc::ENOSPC) => "no space left on device",
        Some(libc::EROFS) => "read-only file system",
        _ => "",
    };
    if code.is_empty() {
        return format!("Error: {error}");
    }
    format!(
        "Error: {code}: {description}, open '{}'",
        path.display()
    )
}

/// Incremental MurmurHash3 (`imurmurhash`), needed to reproduce the temporary
/// file names of `write-file-atomic`.
struct ImurmurHash {
    h: u32,
    k: u32,
    len: u32,
    rem: u32,
}

impl ImurmurHash {
    fn new() -> ImurmurHash {
        ImurmurHash {
            h: 0,
            k: 0,
            len: 0,
            rem: 0,
        }
    }

    fn hash(&mut self, data: &str) {
        let units: Vec<u32> = data.encode_utf16().map(|unit| unit as u32).collect();
        let top = units.len();
        let mut i = 0usize;
        let mut k = self.k;
        let mut h = self.h;
        let mut rem = self.rem;

        while i < top {
            match rem {
                0 => k = units[i] & 0xffff,
                1 => k |= (units[i] & 0xffff) << 8,
                2 => k |= (units[i] & 0xffff) << 16,
                _ => {
                    k |= (units[i] & 0xff) << 24;
                    h = mix(h, k);
                    k = (units[i] >> 8) & 0xff;
                }
            }
            rem = (rem + 1) % 4;
            i += 1;
        }

        self.h = h;
        self.k = k;
        self.rem = rem;
        self.len = self.len.wrapping_add(top as u32);
    }

    fn result(&self) -> u32 {
        let mut h = self.h;
        let k = self.k;
        if k != 0 {
            let mut k = k.wrapping_mul(0x2d51);
            k = (k & 0xffff).wrapping_add((k >> 16).wrapping_mul(0xcc9e) << 16);
            k = k.rotate_left(15);
            let mut k2 = k.wrapping_mul(0x3593);
            k2 = (k2 & 0xffff).wrapping_add((k2 >> 16).wrapping_mul(0x1b87) << 16);
            h ^= k2;
        }
        h ^= self.len;
        h ^= h >> 16;
        h = h.wrapping_mul(0xca6b);
        h = (h & 0xffff).wrapping_add((h >> 16).wrapping_mul(0x85eb) << 16);
        h ^= h >> 13;
        h = h.wrapping_mul(0xae35);
        h = (h & 0xffff).wrapping_add((h >> 16).wrapping_mul(0xc2b2) << 16);
        h ^= h >> 16;
        h
    }
}

fn mix(mut h: u32, k: u32) -> u32 {
    let mut k = k.wrapping_mul(0x2d51);
    k = (k & 0xffff).wrapping_add((k >> 16).wrapping_mul(0xcc9e) << 16);
    k = k.rotate_left(15);
    let mut k2 = k.wrapping_mul(0x3593);
    k2 = (k2 & 0xffff).wrapping_add((k2 >> 16).wrapping_mul(0x1b87) << 16);
    h ^= k2;
    h = h.rotate_left(13);
    let h2 = h.wrapping_mul(5).wrapping_add(0xe654);
    (h2 & 0xffff).wrapping_add((h2 >> 16).wrapping_mul(0xe654) << 16) | 0
}

