    PathBuf::from(name)
}

pub fn write_file_atomic(filename: &str, data: &str) -> Result<(), String> {
    let path = Path::new(filename);
    let truename = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    let tmpfile = tmp_name(&truename);

    let metadata = fs::metadata(&truename).ok();
    let mode = metadata.as_ref().map(|meta| meta.mode() & 0o7777);
    let owner = metadata.as_ref().map(|meta| (meta.uid(), meta.gid()));

    let result = (|| -> std::io::Result<()> {
        let mut options = OpenOptions::new();
        options.write(true).create(true).truncate(true);
        if let Some(mode) = mode {
            options.mode(mode);
        }
        let mut file: File = options.open(&tmpfile)?;
        file.write_all(data.as_bytes())?;
        file.sync_all()?;
        drop(file);

        if let Some((uid, gid)) = owner {
            chown(&tmpfile, uid, gid)?;
        }
        if let Some(mode) = mode {
            fs::set_permissions(&tmpfile, PermissionsExt::from_mode(mode))?;
        }
        fs::rename(&tmpfile, &truename)?;
        Ok(())
    })();

    match result {
        Ok(()) => Ok(()),
        Err(error) => {
            let _ = fs::remove_file(&tmpfile);
            Err(format_error(&error, &tmpfile))
        }
    }
}

fn chown(path: &Path, uid: u32, gid: u32) -> std::io::Result<()> {
    let c_path = std::ffi::CString::new(path.as_os_str().as_encoded_bytes())
        .map_err(|_| std::io::Error::from(std::io::ErrorKind::InvalidInput))?;
    if unsafe { libc::chown(c_path.as_ptr(), uid, gid) } == 0 {
        return Ok(());
    }
    let error = std::io::Error::last_os_error();
    // `isChownErrOk`: unprivileged processes may not be able to change the
    // owner, which the JavaScript implementation tolerates.
    let code = error.raw_os_error().unwrap_or(0);
    let nonroot = unsafe { libc::getuid() } != 0;
    if code == libc::ENOSYS || (nonroot && (code == libc::EINVAL || code == libc::EPERM)) {
        return Ok(());
    }
    Err(error)
}

/// Formats an `io::Error` like the `Error` objects Node passes to the
/// `writeFileAtomic` callback, which the runner interpolates into its output.
fn format_error(error: &std::io::Error, path: &Path) -> String {
    let (code, description) = match error.raw_os_error() {
        Some(libc::ENOENT) => ("ENOENT", "no such file or directory"),
        Some(libc::EACCES) => ("EACCES", "permission denied"),
        Some(libc::EPERM) => ("EPERM", "operation not permitted"),
        Some(libc::EISDIR) => ("EISDIR", "illegal operation on a directory"),
        Some(libc::ENOSPC) => ("ENOSPC", "no space left on device"),
        Some(libc::EROFS) => ("EROFS", "read-only file system"),
        _ => return format!("Error: {error}"),
    };
    format!("Error: {code}: {description}, open '{}'", path.display())
}

