{"command":"create","path":"/workspace/codebase/rust/src/runner.rs","file_text":"//! Port of `src/Runner.js`: file discovery, worker management, status
//! reporting and the final summary.

use crate::colors as pc;
use crate::ignore_files::IgnoreFiles;
use crate::node_path as path;
use crate::worker::{self, WorkerMessage};
use crate::write_file_atomic::write_file_atomic;
use serde_json::{Map, Value};
use std::collections::BTreeMap;
use std::fs;
use std::io::{self, Write};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

fn available_cpus() -> usize {
    num_cpus::get().saturating_sub(1).max(1)
}

fn line_break(value: &str) -> String {
    if value.ends_with('\n') {
        value.to_string()
    } else {
        format!("{value}\n")
    }
}

fn write_stdout(message: &str) {
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(message.as_bytes());
    let _ = handle.flush();
}

fn write_stderr(message: &str) {
    let stderr = io::stderr();
    let mut handle = stderr.lock();
    let _ = handle.write_all(message.as_bytes());
    let _ = handle.flush();
}

#[derive(Default)]
struct FileCounters {
    error: usize,
    ok: usize,
    nochange: usize,
    skip: usize,
}

impl FileCounters {
    fn increment(&mut self, status: &str) {
        match status {
            "error" => self.error += 1,
            "ok" => self.ok += 1,
            "nochange" => self.nochange += 1,
            "skip" => self.skip += 1,
            _ => {}
        }
    }
}

fn log(status: &str, message: &str, verbose: i64) {
    let rendered = match status {
        "ok" => {
            if verbose < 2 {
                return;
            }
            format!("{}{message}", pc::bg_green(&pc::white(" OKK ")))
        }
        "nochange" => {
            if verbose < 1 {
                return;
            }
            format!("{}{message}", pc::bg_yellow(&pc::white(" NOC ")))
        }
        "skip" => {
            if verbose < 1 {
                return;
            }
            format!("{}{message}", pc::bg_yellow(&pc::white(" SKIP ")))
        }
        "error" => {
            if verbose < 0 {
                return;
            }
            format!("{}{message}", pc::bg_red(&pc::white(" ERR ")))
        }
        _ => return,
    };
    write_stdout(&rendered);
}

fn report(file: &str, msg: &str) {
    write_stdout(&line_break(&format!(
        "{}{file} {msg}",
        pc::bg_blue(&pc::white(" REP "))
    )));
}

fn show_file_stats(counters: &FileCounters) {
    write_stdout(&format!(
        "Results: \n{}{}{}{}",
        pc::red(&format!("{} errors\n", counters.error)),
        pc::yellow(&format!("{} unmodified\n", counters.nochange)),
        pc::yellow(&format!("{} skipped\n", counters.skip)),
        pc::green(&format!("{} ok\n", counters.ok)),
    ));
}

fn show_stats(stats: &BTreeMap<String, f64>) {
    if !stats.is_empty() {
        write_stdout(&pc::blue("Stats: \n"));
    }
    for (name, quantity) in stats {
        write_stdout(&format!("{name}: {}\n", format_number(*quantity)));
    }
}

/// JavaScript number formatting for the accumulated `stats` counters.
fn format_number(value: f64) -> String {
    if value.fract() == 0.0 && value.abs() < 1e21 {
        format!("{}", value as i64)
    } else {
        let mut rendered = format!("{value}");
        if rendered.ends_with(".0") {
            rendered.truncate(rendered.len() - 2);
        }
        rendered
    }
}

fn dir_files(dir: &str, ignores: &mut IgnoreFiles, files: &mut Vec<String>) {
    let entries = match fs::read_dir(dir) {
        Ok(entries) => entries,
        // `if (err) throw err` — should not happen because callers check first.
        Err(error) => {
            write_stderr(&format!("{error}\n"));
            return;
        }
    };
    for entry in entries.flatten() {
        let name = path::join(dir, &entry.file_name().to_string_lossy());
        match fs::metadata(&name) {
            Err(_) => {
                // Probably a symlink issue.
                write_stdout(&format!(
                    "Skipping path \"{name}\" which does not exist.\n"
                ));
            }
            Ok(metadata) => {
                if ignores.should_ignore(&name) {
                    continue;
                }
                if metadata.is_dir() {
                    dir_files(&format!("{name}/"), ignores, files);
                } else {
                    files.push(name);
                }
            }
        }
    }
}

fn get_all_files(
    paths: &[String],
    extensions: Option<&Vec<String>>,
    ignores: &mut IgnoreFiles,
) -> Vec<String> {
    let filter = |name: &str| match extensions {
        Some(extensions) => extensions.iter().any(|ext| ext == &path::extname(name)),
        None => true,
    };

    let mut result = Vec::new();
    for file in paths {
        match fs::symlink_metadata(file) {
            Err(_) => {
                write_stderr(&format!(
                    "Skipping path {file} which does not exist. \n"
                ));
            }
            Ok(metadata) => {
                if metadata.is_dir() {
                    let mut found = Vec::new();
                    dir_files(file, ignores, &mut found);
                    result.extend(found.into_iter().filter(|name| filter(name)));
                } else if !filter(file) || ignores.should_ignore(file) {
                    // Ignoring the file.
                } else {
                    result.push(file.clone());
                }
            }
        }
    }
    result
}

pub struct RunResult {
    pub stats: BTreeMap<String, f64>,
    pub time_elapsed: String,
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
    /// Set when `failOnError` triggered the `process.exit(1)` of the runner.
    pub should_exit_with_error: bool,
}

impl RunResult {
    pub fn to_json(&self) -> Value {
        let mut stats = Map::new();
        for (name, quantity) in &self.stats {
            stats.insert(name.clone(), Value::from(*quantity));
        }
        let mut result = Map::new();
        result.insert("stats".to_string(), Value::Object(stats));
        result.insert(
            "timeElapsed".to_string(),
            Value::String(self.time_elapsed.clone()),
        );
        result.insert("error".to_string(), Value::from(self.error));
        result.insert("ok".to_string(), Value::from(self.ok));
        result.insert("nochange".to_string(), Value::from(self.nochange));
        result.insert("skip".to_string(), Value::from(self.skip));
        Value::Object(result)
    }
}

fn option_bool(options: &Map<String, Value>, key: &str) -> bool {
    matches!(options.get(key), Some(Value::Bool(true)))
}

fn option_usize(options: &Map<String, Value>, key: &str) -> Option<usize> {
    match options.get(key) {
        Some(Value::Number(number)) => number.as_f64().and_then(|value| {
            if value.is_finite() && value >= 1.0 {
                Some(value as usize)
            } else {
                None
            }
        }),
        _ => None,
    }
}

fn verbose_level(options: &Map<String, Value>) -> i64 {
    options
        .get("verbose")
        .and_then(|value| value.as_i64())
        .unwrap_or(0)
}

/// `run(transformFile, paths, options)`.
///
/// Returns `None` when the transform file does not exist, matching the
/// `undefined` return of the JavaScript implementation.
pub fn run(
    transform_file: &str,
    paths: &[String],
    options: &Map<String, Value>,
) -> Result<Option<RunResult>, String> {
    let cpus = match option_usize(options, "cpus") {
        Some(cpus) => available_cpus().min(cpus),
        None => available_cpus(),
    };
    let extensions: Option<Vec<String>> = options
        .get("extensions")
        .and_then(|value| value.as_str())
        .map(|value| value.split(',').map(|ext| format!(".{ext}")).collect());
    let start_time = Instant::now();

    let mut ignores = IgnoreFiles::new();
    ignores.add(options.get("ignoreSet"));
    ignores.add(options.get("ignorePattern"));
    ignores.add_from_file(options.get("ignoreConfig"))?;

    if option_bool(options, "gitignore") {
        let curr_directory = std::env::current_dir()
            .map(|dir| dir.to_string_lossy().to_string())
            .unwrap_or_default();
        let git_ignore_path = path::join(&curr_directory, ".gitignore");
        ignores.add_from_file(Some(&Value::String(git_ignore_path)))?;
    }

    if transform_file.starts_with("http") {
        let downloaded = download_transform(transform_file)?;
        return Ok(Some(transform(
            downloaded.path(),
            paths,
            options,
            cpus,
            extensions.as_ref(),
            &mut ignores,
            start_time,
        )?));
    }

    if fs::metadata(transform_file).is_err() {
        write_stderr(&format!(
            "{} Transform file {transform_file} does not exist \n",
            pc::bg_red(&pc::white("ERROR"))
        ));
        return Ok(None);
    }

    Ok(Some(transform(
        transform_file,
        paths,
        options,
        cpus,
        extensions.as_ref(),
        &mut ignores,
        start_time,
    )?))
}

/// Downloads a remote transform into a temporary file, keeping the extension of
/// the URL so that the babel setup can detect TypeScript transforms.
struct DownloadedTransform {
    _dir: tempfile::TempDir,
    path: String,
}

impl DownloadedTransform {
    fn path(&self) -> &str {
        &self.path
    }
}

fn download_transform(url: &str) -> Result<DownloadedTransform, String> {
    let response = ureq::get(url).call().map_err(|error| error.to_string())?;
    let contents = response
        .into_string()
        .map_err(|error| error.to_string())?;
    let ext = path::extname(url);
    let dir = tempfile::Builder::new()
        .prefix("jscodeshift")
        .tempdir()
        .map_err(|error| error.to_string())?;
    let file = dir.path().join(format!("jscodeshift{ext}"));
    fs::write(&file, contents).map_err(|error| error.to_string())?;
    Ok(DownloadedTransform {
        path: file.to_string_lossy().to_string(),
        _dir: dir,
    })
}

struct Shared {
    file_counters: FileCounters,
    stats_counter: BTreeMap<String, f64>,
    verbose: i64,
    dry: bool,
}

#[allow(clippy::too_many_arguments)]
fn transform(
    transform_file: &str,
    paths: &[String],
    options: &Map<String, Value>,
    cpus: usize,
    extensions: Option<&Vec<String>>,
    ignores: &mut IgnoreFiles,
    start_time: Instant,
) -> Result<RunResult, String> {
    let silent = option_bool(options, "silent");
    let run_in_band = option_bool(options, "runInBand");
    let dry = option_bool(options, "dry");
    let files = get_all_files(paths, extensions, ignores);
    let num_files = files.len();

    let shared = Arc::new(Mutex::new(Shared {
        file_counters: FileCounters::default(),
        stats_counter: BTreeMap::new(),
        verbose: verbose_level(options),
        dry,
    }));

    if num_files == 0 {
        write_stdout("No files selected, nothing to do. \n");
    } else {
        let processes = if run_in_band { 1 } else { num_files.min(cpus) };
        let chunk_size = if processes > 1 {
            num_files.div_ceil(processes).min(CHUNK_SIZE)
        } else {
            num_files
        };

        if !silent {
            write_stdout(&format!("Processing {num_files} files... \n"));
            if !run_in_band {
                write_stdout(&format!("Spawning {processes} workers...\n"));
            }
            if dry {
                write_stdout(&pc::green(
                    "Running in dry mode, no files will be written! \n",
                ));
            }
        }

        let index = Arc::new(Mutex::new(0usize));
        let files = Arc::new(files);
        let mut handles = Vec::new();
        for _ in 0..processes {
            let shared = Arc::clone(&shared);
            let index = Arc::clone(&index);
            let files = Arc::clone(&files);
            let options = options.clone();
            let transform_file = transform_file.to_string();
            handles.push(std::thread::spawn(move || {
                run_worker(
                    &transform_file,
                    &files,
                    &index,
                    chunk_size,
                    &options,
                    shared,
                    silent,
                    run_in_band,
                )
            }));
        }
        for handle in handles {
            if let Err(error) = handle.join().map_err(|_| "worker panicked".to_string())? {
                return Err(error);
            }
        }
    }

    let elapsed = start_time.elapsed();
    let time_elapsed = format!("{:.3}", elapsed.as_secs_f64());
    let mut shared = shared.lock().unwrap();
    let counters = std::mem::take(&mut shared.file_counters);
    let stats = std::mem::take(&mut shared.stats_counter);
    let mut should_exit_with_error = false;

    if !silent {
        write_stdout("All done. \n");
        show_file_stats(&counters);
        show_stats(&stats);
        write_stdout(&format!("Time elapsed: {time_elapsed}seconds \n"));

        if option_bool(options, "failOnError") && counters.error > 0 {
            should_exit_with_error = true;
        }
    }

    Ok(RunResult {
        stats,
        time_elapsed,
        error: counters.error,
        ok: counters.ok,
        nochange: counters.nochange,
        skip: counters.skip,
        should_exit_with_error,
    })
}

/// Returns the next chunk of work for a free worker.
fn next_chunk(
    files: &[String],
    index: &Mutex<usize>,
    chunk_size: usize,
    silent: bool,
    run_in_band: bool,
) -> Vec<String> {
    let mut index = index.lock().unwrap();
    let num_files = files.len();
    if !silent && !run_in_band && *index < num_files {
        write_stdout(&format!(
            "Sending {} files to free worker...\n",
            chunk_size.min(num_files - *index)
        ));
    }
    let start = *index;
    let end = (start + chunk_size).min(num_files);
    *index = start + chunk_size;
    files[start..end].to_vec()
}

#[allow(clippy::too_many_arguments)]
fn run_worker(
    transform_file: &str,
    files: &[String],
    index: &Mutex<usize>,
    chunk_size: usize,
    options: &Map<String, Value>,
    shared: Arc<Mutex<Shared>>,
    silent: bool,
    run_in_band: bool,
) -> Result<(), String> {
    let mut child = worker::spawn(transform_file, options)?;
    // Files that are still being processed by the worker, so that a status can
    // be reported for the ones a crashing worker never answered for.
    let pending: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
    let done = AtomicBool::new(false);

    let mut send_next = |child: &mut worker::Worker| -> Result<bool, String> {
        let chunk = next_chunk(files, index, chunk_size, silent, run_in_band);
        if chunk.is_empty() {
            child.finish()?;
            return Ok(false);
        }
        let mut sources = Vec::with_capacity(chunk.len());
        for file in chunk {
            match fs::read(&file) {
                Ok(bytes) => {
                    sources.push((file, String::from_utf8_lossy(&bytes).to_string()));
                }
                Err(error) => {
                    update_status(
                        &shared,
                        "error",
                        &file,
                        Some(&format!("File error: {}", node_read_error(&file, &error))),
                    );
                }
            }
        }
        if sources.is_empty() {
            // Every file of the batch failed to be read; ask for more work.
            return Ok(true);
        }
        pending
            .lock()
            .unwrap()
            .extend(sources.iter().map(|(file, _)| file.clone()));
        child.send(&sources, options)?;
        Ok(true)
    };

    if !send_next(&mut child)? {
        done.store(true, Ordering::SeqCst);
    }

    while !done.load(Ordering::SeqCst) {
        match child.next_message()? {
            None => break,
            Some(WorkerMessage::Free) => {
                if !send_next(&mut child)? {
                    done.store(true, Ordering::SeqCst);
                }
            }
            Some(WorkerMessage::Report { file, msg }) => report(&file, &msg),
            Some(WorkerMessage::Update { name, quantity }) => {
                let mut shared = shared.lock().unwrap();
                *shared.stats_counter.entry(name).or_insert(0.0) += quantity;
            }
            Some(WorkerMessage::Error { file, msg }) => {
                pending.lock().unwrap().retain(|pending| pending != &file);
                update_status(&shared, "error", &file, Some(&msg));
            }
            Some(WorkerMessage::Transformed {
                file,
                out,
                truthy,
                changed,
            }) => {
                pending.lock().unwrap().retain(|pending| pending != &file);
                if !changed {
                    update_status(
                        &shared,
                        if truthy { "nochange" } else { "skip" },
                        &file,
                        None,
                    );
                    continue;
                }
                let dry = shared.lock().unwrap().dry;
                if dry {
                    update_status(&shared, "ok", &file, None);
                    continue;
                }
                match write_file_atomic(&file, out.as_deref().unwrap_or("")) {
                    Ok(()) => update_status(&shared, "ok", &file, None),
                    Err(error) => update_status(
                        &shared,
                        "error",
                        &file,
                        Some(&format!("File writer error: {error}")),
                    ),
                }
            }
        }
    }

    child.wait()?;
    Ok(())
}

fn update_status(shared: &Mutex<Shared>, status: &str, file: &str, msg: Option<&str>) {
    let message = match msg {
        Some(msg) => format!("{file} {msg}"),
        None => file.to_string(),
    };
    let mut shared = shared.lock().unwrap();
    shared.file_counters.increment(status);
    let verbose = shared.verbose;
    drop(shared);
    log(status, &line_break(&message), verbose);
}

/// The `Error` string Node produces for a failed `fs.readFile`.
fn node_read_error(file: &str, error: &std::io::Error) -> String {
    let (code, description) = match error.raw_os_error() {
        Some(libc::ENOENT) => ("ENOENT", "no such file or directory"),
        Some(libc::EACCES) => ("EACCES", "permission denied"),
        Some(libc::EISDIR) => ("EISDIR", "illegal operation on a directory"),
        _ => return format!("Error: {error}"),
    };
    if code == "EISDIR" {
        return format!("Error: {code}: {description}, read");
    }
    format!("Error: {code}: {description}, open '{file}'")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn formats_stat_numbers_like_javascript() {
        assert_eq!(format_number(1.0), "1");
        assert_eq!(format_number(2.5), "2.5");
    }

    #[test]
    fn adds_missing_trailing_newline() {
        assert_eq!(line_break("a"), "a\n");
        assert_eq!(line_break("a\n"), "a\n");
    }
}
