{"command":"create","path":"/workspace/codebase/rust/src/worker.rs","file_text":"//! Spawns and talks to the JavaScript compatibility bridge that loads and runs
//! transform modules (`src/Worker.js` in the JavaScript implementation).
//!
//! Work batches are written to the child's stdin as line delimited JSON, and
//! the child reports back on file descriptor 3 so that stdout and stderr stay
//! reserved for whatever the transform itself prints.

use serde_json::{json, Map, Value};
use std::io::{BufRead, BufReader, Write};
use std::os::unix::io::{FromRawFd, RawFd};
use std::os::unix::process::CommandExt;
use std::process::{Child, ChildStdin, Command, Stdio};

pub enum WorkerMessage {
    Free,
    Report {
        file: String,
        msg: String,
    },
    Update {
        name: String,
        quantity: f64,
    },
    Error {
        file: String,
        msg: String,
    },
    Transformed {
        file: String,
        out: Option<String>,
        /// Whether the transform returned a truthy value.
        truthy: bool,
        /// Whether the returned source differs from the input.
        changed: bool,
    },
}

pub struct Worker {
    child: Child,
    stdin: Option<ChildStdin>,
    notifications: BufReader<std::fs::File>,
}

fn bridge_path() -> Result<String, String> {
    let exe = std::env::current_exe().map_err(|error| error.to_string())?;
    // The binary is installed inside the package, so the bridge is resolved
    // relative to it.
    let mut dir = exe.parent().map(|dir| dir.to_path_buf());
    while let Some(candidate) = dir {
        let bridge = candidate.join("bridge/transform-host.js");
        if bridge.exists() {
            return Ok(bridge.to_string_lossy().to_string());
        }
        dir = candidate.parent().map(|dir| dir.to_path_buf());
    }
    Err("Unable to locate the jscodeshift transform bridge".to_string())
}

fn node_binary() -> String {
    std::env::var("JSCODESHIFT_NODE").unwrap_or_else(|_| "node".to_string())
}

pub fn spawn(transform_file: &str, options: &Map<String, Value>) -> Result<Worker, String> {
    let babel = if matches!(options.get("babel"), Some(Value::Bool(false))) {
        "no-babel"
    } else {
        "babel"
    };

    let (read_fd, write_fd) = create_pipe()?;

    let mut command = Command::new(node_binary());
    command
        .arg(bridge_path()?)
        .arg(transform_file)
        .arg(babel)
        .stdin(Stdio::piped())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    unsafe {
        command.pre_exec(move || {
            if libc::dup2(write_fd, 3) == -1 {
                return Err(std::io::Error::last_os_error());
            }
            libc::close(read_fd);
            if write_fd != 3 {
                libc::close(write_fd);
            }
            Ok(())
        });
    }

    let mut child = command.spawn().map_err(|error| {
        close_fd(read_fd);
        close_fd(write_fd);
        format!("Unable to start the jscodeshift transform bridge: {error}")
    })?;
    close_fd(write_fd);

    let stdin = child.stdin.take();
    let notifications = unsafe { std::fs::File::from_raw_fd(read_fd) };

    Ok(Worker {
        child,
        stdin,
        notifications: BufReader::new(notifications),
    })
}

fn create_pipe() -> Result<(RawFd, RawFd), String> {
    let mut fds: [libc::c_int; 2] = [0; 2];
    if unsafe { libc::pipe(fds.as_mut_ptr()) } != 0 {
        return Err(std::io::Error::last_os_error().to_string());
    }
    Ok((fds[0], fds[1]))
}

fn close_fd(fd: RawFd) {
    unsafe {
        libc::close(fd);
    }
}

impl Worker {
    pub fn send(
        &mut self,
        files: &[(String, String)],
        options: &Map<String, Value>,
    ) -> Result<(), String> {
        let payload = json!({
            "files": files
                .iter()
                .map(|(path, source)| json!({"path": path, "source": source}))
                .collect::<Vec<Value>>(),
            "options": Value::Object(options.clone()),
        });
        let stdin = match self.stdin.as_mut() {
            Some(stdin) => stdin,
            None => return Ok(()),
        };
        writeln!(stdin, "{payload}").map_err(|error| error.to_string())?;
        stdin.flush().map_err(|error| error.to_string())
    }

    /// Signals that no work is left, which lets the child exit.
    pub fn finish(&mut self) -> Result<(), String> {
        self.stdin = None;
        Ok(())
    }

    pub fn next_message(&mut self) -> Result<Option<WorkerMessage>, String> {
        let mut line = String::new();
        loop {
            line.clear();
            let read = self
                .notifications
                .read_line(&mut line)
                .map_err(|error| error.to_string())?;
            if read == 0 {
                return Ok(None);
            }
            let trimmed = line.trim_end_matches('\n');
            if trimmed.is_empty() {
                continue;
            }
            let message: Value =
                serde_json::from_str(trimmed).map_err(|error| error.to_string())?;
            return Ok(Some(parse_message(&message)?));
        }
    }

    pub fn wait(&mut self) -> Result<(), String> {
        self.stdin = None;
        self.child
            .wait()
            .map(|_| ())
            .map_err(|error| error.to_string())
    }
}

fn parse_message(message: &Value) -> Result<WorkerMessage, String> {
    let action = message
        .get("action")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let file = message
        .get("file")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    match action {
        "free" => Ok(WorkerMessage::Free),
        "report" => Ok(WorkerMessage::Report {
            file,
            msg: message
                .get("msg")
                .and_then(|value| value.as_str())
                .unwrap_or_default()
                .to_string(),
        }),
        "update" => Ok(WorkerMessage::Update {
            name: message
                .get("name")
                .and_then(|value| value.as_str())
                .unwrap_or_default()
                .to_string(),
            quantity: message
                .get("quantity")
                .and_then(|value| value.as_f64())
                .unwrap_or(1.0),
        }),
        "error" => Ok(WorkerMessage::Error {
            file,
            msg: message
                .get("msg")
                .and_then(|value| value.as_str())
                .unwrap_or_default()
                .to_string(),
        }),
        "transformed" => {
            let out = message
                .get("out")
                .and_then(|value| value.as_str())
                .map(|value| value.to_string());
            Ok(WorkerMessage::Transformed {
                file,
                truthy: out.as_ref().map(|out| !out.is_empty()).unwrap_or(false),
                changed: matches!(message.get("changed"), Some(Value::Bool(true))),
                out,
            })
        }
        other => Err(format!("Unknown worker message: {other}")),
    }
}
