struct Hooks;

impl ProcessHooks for Hooks {
    fn read_json_file(&self, path: &str) -> Result<Value, String> {
        let contents = std::fs::read(path).map_err(|error| match error.kind() {
            std::io::ErrorKind::NotFound => format!(
                "Error: ENOENT: no such file or directory, open '{path}'"
            ),
            _ => format!("Error: {error}"),
