use crate::node_path as path;
use serde_json::Value;
use std::fs;
use std::path::{Path, PathBuf};

/// Root of the installed package, located relative to the executable.
fn package_root() -> Option<PathBuf> {
    let exe = std::env::current_exe().ok()?;
    let mut dir = exe.parent().map(|dir| dir.to_path_buf());
    while let Some(candidate) = dir {
        if candidate.join("bridge/transform-host.js").exists() {
            return Some(candidate);
        }
        dir = candidate.parent().map(|dir| dir.to_path_buf());
    }
    None
}

fn read_package_json(path: &Path) -> Option<Value> {
    let contents = fs::read_to_string(path).ok()?;
    serde_json::from_str(&contents).ok()
}

fn own_version() -> String {
    package_root()
        .and_then(|root| read_package_json(&root.join("package.json")))
        .and_then(|pkg| pkg.get("version").and_then(|v| v.as_str().map(String::from)))
        .unwrap_or_default()
}

/// `requirePackage(name)`: resolves the module and walks up from its entry file
/// until a `package.json` with a matching name is found.
fn require_package(name: &str) -> Value {
    let entry = match resolve_module(name) {
        Some(entry) => entry,
        None => return Value::Object(Default::default()),
    };
    let mut dir = path::dirname(&entry.to_string_lossy());
    while dir != "/" {
        if let Some(pkg) = read_package_json(Path::new(&path::join(&dir, "package.json"))) {
            return if pkg.get("name").and_then(|value| value.as_str()) == Some(name) {
                pkg
            } else {
                Value::Object(Default::default())
            };
        }
        dir = path::dirname(&dir);
    }
    Value::Object(Default::default())
}

/// `require.resolve(name)` for the flat and nested `node_modules` layouts the
/// package can be installed with.
fn resolve_module(name: &str) -> Option<PathBuf> {
    let mut dir = package_root();
    while let Some(candidate) = dir {
        let module_dir = candidate.join("node_modules").join(name);
        if module_dir.exists() {
            let pkg = read_package_json(&module_dir.join("package.json"));
            let main = pkg
                .as_ref()
                .and_then(|pkg| pkg.get("main"))
                .and_then(|value| value.as_str())
                .unwrap_or("index.js");
            let entry = module_dir.join(main);
            return Some(if entry.exists() {
                entry
            } else {
                module_dir.join("index.js")
            });
        }
        dir = candidate.parent().map(|dir| dir.to_path_buf());
    }
    None
}

fn package_version(name: &str) -> String {
    require_package(name)
        .get("version")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string()
}

pub fn version_text() -> String {
    [
        format!("jscodeshift: {}", own_version()),
        format!(" - babel: {}", package_version("@babel/core")),
        format!(" - babylon: {}", package_version("@babel/parser")),
        format!(" - flow: {}", package_version("flow-parser")),
        format!(" - recast: {}\n", package_version("recast")),
    ]
    .join("\n")
}
