/**
 * Public entry point of the programmatic runner API. The runner itself is
 * implemented in Rust; this module forwards the call to the `jscodeshift`
 * binary and returns its result.
 */

'use strict';

const child_process = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const binary = require('../bridge/binary');

function run(transformFile, paths, options) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jscodeshift-api-'));
  const requestPath = path.join(dir, 'request.json');
  const responsePath = path.join(dir, 'response.json');

  fs.writeFileSync(
    requestPath,
    JSON.stringify({transformFile, paths, options: options || {}})
  );

  const result = child_process.spawnSync(binary.path(), [], {
    stdio: 'inherit',
    env: Object.assign({}, process.env, {
      JSCODESHIFT_API_REQUEST: requestPath,
      JSCODESHIFT_API_RESPONSE: responsePath,
    }),
  });

  let response = null;
  try {
    response = JSON.parse(fs.readFileSync(responsePath, 'utf8'));
  } catch (_) {}
  fs.rmSync(dir, {recursive: true, force: true});

  if (result.error) {
    return Promise.reject(result.error);
  }
  if (response && response.error) {
    return Promise.reject(new Error(response.error));
  }
  if (response && response.exit) {
    process.exit(1);
  }
  return Promise.resolve(response ? response.result : undefined);
}

exports.run = run;
