/// `http.get` request does, e.g. `connect ECONNREFUSED 127.0.0.1:1`.
fn node_connect_error(url: &str, transport: &ureq::Transport) -> String {
    let message = transport.to_string();
    let authority = url
        .split_once("//")
        .map(|(_, rest)| rest.split('/').next().unwrap_or(rest))
        .unwrap_or(url);
    let default_port = if url.starts_with("https") { 443 } else { 80 };
    let target = if authority.rsplit_once(':').is_some_and(|(_, port)| {
        !port.is_empty() && port.chars().all(|character| character.is_ascii_digit())
    }) {
        authority.to_string()
    } else {
        format!("{authority}:{default_port}")
    };

    let code = if message.contains("Connection refused") {
        "ECONNREFUSED"
    } else if message.contains("timed out") || message.contains("timeout") {
        "ETIMEDOUT"
    } else if message.contains("dns") || message.contains("Dns") {
        return format!("Error: getaddrinfo ENOTFOUND {}\n", authority.split(':').next().unwrap_or(authority));
    } else {
        "ECONNRESET"
    };
    format!("Error: connect {code} {target}\n")
}

