 */

/**
 * Downloads a remote transform into a temporary file and writes the resulting
 * path to file descriptor 3. Fetching remote transforms stays in JavaScript so
 * that request failures keep producing the exact unhandled rejection Node
 * reports, which is part of the observable behavior of the command.
 *
 * The runner removes the temporary file once the run is over, taking over the
 * cleanup `tmp` performed at process exit while the download happened in the
 * runner's own process.
 */

'use strict';

const fs = require('graceful-fs');
const http = require('http');
const https = require('https');
const path = require('path');
const tmp = require('tmp');

const transformFile = process.argv[2];

new Promise((resolve, reject) => {
  // call the correct `http` or `https` implementation
  (transformFile.indexOf('https') !== 0 ? http : https).get(transformFile, (res) => {
    let contents = '';
    res
      .on('data', (d) => {
        contents += d.toString();
      })
      .on('end', () => {
        const ext = path.extname(transformFile);
        tmp.file({ prefix: 'jscodeshift', postfix: ext, keep: true }, (err, path, fd) => {
          if (err) return reject(err);
          fs.write(fd, contents, function (err) {
            if (err) return reject(err);
            fs.close(fd, function (err) {
              if (err) return reject(err);
              resolve(path);
            });
          });
        });
      })
  })
  .on('error', (e) => {
    reject(e);
  });
}).then(path => {
  fs.writeSync(3, path + '\n');
});
