/// Downloads a remote transform through the JavaScript bridge and returns the
/// path of the temporary file it was stored in.
///
/// `Ok(None)` means the request failed and the bridge already reported it.
pub fn download_transform(url: &str) -> Result<Option<String>, String> {
    let (read_fd, write_fd) = create_pipe()?;

    let mut command = Command::new(node_binary());
    command
        .arg(bridge_path("download-transform.js")?)
        .arg(url)
        .stdin(Stdio::null())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    unsafe {
        command.pre_exec(move || {
            if read_fd != write_fd {
                libc::close(read_fd);
            }
            if write_fd != 3 {
                if libc::dup2(write_fd, 3) == -1 {
                    return Err(std::io::Error::last_os_error());
                }
                libc::close(write_fd);
            }
            Ok(())
        });
    }

    let mut child = command.spawn().map_err(|error| {
        close_fd(read_fd);
        close_fd(write_fd);
        format!("Unable to start the jscodeshift transform bridge: {error}")
    })?;
    close_fd(write_fd);

    let mut path = String::new();
    let mut reader = BufReader::new(unsafe { std::fs::File::from_raw_fd(read_fd) });
    reader
        .read_line(&mut path)
        .map_err(|error| error.to_string())?;
    let status = child.wait().map_err(|error| error.to_string())?;
    if !status.success() {
        return Ok(None);
    }
    Ok(Some(path.trim_end_matches('\n').to_string()))
